//! Example: Custom MCP (Model Context Protocol) Node
//!
//! This example demonstrates how to implement a custom node that integrates
//! with Model Context Protocol servers. MCP nodes are service-specific and
//! should be registered dynamically by users, not built into the engine.
//!
//! ## Key Concepts
//!
//! 1. **Implement the `Node` trait** — Define node type and execution logic
//! 2. **Register dynamically** — Add to `NodeRegistry` before creating engine
//! 3. **Access shared context** — Read/write global context via `ctx.context`
//! 4. **Use Jinja2 templates** — Render dynamic arguments from upstream data
//!
//! ## Running this example
//!
//! ```bash
//! cargo run --example custom_mcp_node
//! ```

use a3s_flow::{
    DagGraph, ExecContext, FlowEngine, FlowError, Node, NodeRegistry, Result as FlowResult,
};
use async_trait::async_trait;
use serde::Deserialize;
use serde_json::{json, Value};
use std::collections::HashMap;
use std::sync::Arc;

/// MCP node configuration (parsed from `data` field in flow definition)
#[derive(Debug, Deserialize)]
struct McpConfig {
    /// MCP server URL (e.g., "http://localhost:3000")
    server_url: String,
    /// Tool name to call on the MCP server
    tool_name: String,
    /// Transport protocol: "sse" or "http" (default: "sse")
    #[serde(default = "default_transport")]
    transport: String,
    /// Arguments to pass to the tool (supports Jinja2 templates)
    #[serde(default)]
    arguments: HashMap<String, Value>,
}

fn default_transport() -> String {
    "sse".to_string()
}

/// Custom MCP node implementation
pub struct McpNode;

#[async_trait]
impl Node for McpNode {
    fn node_type(&self) -> &str {
        "mcp"
    }

    async fn execute(&self, ctx: ExecContext) -> FlowResult<Value> {
        // Parse node configuration
        let config: McpConfig = serde_json::from_value(ctx.data.clone())
            .map_err(|e| FlowError::InvalidDefinition(format!("invalid mcp node config: {}", e)))?;

        // Example: Read from shared context (Dify-style global context)
        let conversation_id = {
            let context = ctx.context.read().unwrap();
            context
                .get("conversation_id")
                .and_then(|v| v.as_str())
                .unwrap_or("default")
                .to_string()
        };

        // Example: Render Jinja2 templates in arguments (simplified here)
        let rendered_args = self.render_arguments(&config.arguments, &ctx)?;

        // Simulate MCP tool call (in real implementation, use MCP client library)
        println!(
            "[MCP] Calling tool '{}' on server '{}' (transport: {})",
            config.tool_name, config.server_url, config.transport
        );
        println!("[MCP] Conversation ID: {}", conversation_id);
        println!("[MCP] Arguments: {:?}", rendered_args);

        // Simulate response
        let response = json!({
            "text": format!("Response from {} tool", config.tool_name),
            "content": [
                {
                    "type": "text",
                    "text": "This is a simulated MCP response"
                }
            ],
            "is_error": false
        });

        // Example: Write to shared context
        {
            let mut context = ctx.context.write().unwrap();
            context.insert(
                "last_mcp_call".to_string(),
                json!({
                    "tool": config.tool_name,
                    "timestamp": chrono::Utc::now().to_rfc3339()
                }),
            );
        }

        Ok(response)
    }
}

impl McpNode {
    /// Render Jinja2 templates in arguments (simplified version)
    fn render_arguments(
        &self,
        arguments: &HashMap<String, Value>,
        ctx: &ExecContext,
    ) -> FlowResult<HashMap<String, Value>> {
        let mut rendered = HashMap::new();

        for (key, value) in arguments {
            // In real implementation, use minijinja to render templates
            // For now, just pass through and substitute {{variables.x}} patterns
            let rendered_value = if let Some(s) = value.as_str() {
                if s.starts_with("{{") && s.ends_with("}}") {
                    // Extract variable name (simplified)
                    let var_name = s.trim_start_matches("{{").trim_end_matches("}}").trim();
                    if let Some(var_path) = var_name.strip_prefix("variables.") {
                        ctx.variables.get(var_path).cloned().unwrap_or(Value::Null)
                    } else {
                        value.clone()
                    }
                } else {
                    value.clone()
                }
            } else {
                value.clone()
            };

            rendered.insert(key.clone(), rendered_value);
        }

        Ok(rendered)
    }
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    // 1. Create a custom registry with MCP node
    let mut registry = NodeRegistry::with_defaults();
    registry.register(Arc::new(McpNode));

    println!("✓ Registered custom MCP node");
    println!("  Available node types: {:?}\n", registry.list_types());

    // 2. Create a flow that uses the MCP node
    let flow_def = json!({
        "nodes": [
            {
                "id": "init",
                "type": "assign",
                "data": {
                    "assigns": {
                        "query": "What is the weather in San Francisco?"
                    }
                }
            },
            {
                "id": "mcp_call",
                "type": "mcp",
                "data": {
                    "server_url": "http://localhost:3000",
                    "tool_name": "get_weather",
                    "transport": "sse",
                    "arguments": {
                        "location": "{{variables.query}}"
                    }
                }
            },
            {
                "id": "end",
                "type": "end",
                "data": {
                    "outputs": {
                        "result": "/mcp_call/text"
                    }
                }
            }
        ],
        "edges": [
            { "source": "init", "target": "mcp_call" },
            { "source": "mcp_call", "target": "end" }
        ]
    });

    // 3. Parse and validate the flow
    let _dag = DagGraph::from_json(&flow_def)?;
    println!("✓ Flow definition parsed and validated\n");

    // 4. Create engine and execute
    let engine = FlowEngine::new(registry);

    // Set up initial variables (including conversation context)
    let mut variables = HashMap::new();
    variables.insert("conversation_id".to_string(), json!("conv-12345"));

    println!("▶ Starting flow execution...\n");

    // Convert DagGraph to JSON for engine.start()
    let flow_json = serde_json::to_value(&flow_def)?;
    let execution_id = engine.start(&flow_json, variables).await?;

    // 5. Poll for completion
    loop {
        tokio::time::sleep(tokio::time::Duration::from_millis(100)).await;
        let state = engine.state(execution_id).await?;

        match state {
            a3s_flow::ExecutionState::Completed(result) => {
                println!("\n✓ Flow completed successfully");
                println!("  Execution ID: {}", execution_id);
                println!(
                    "  Final outputs: {}",
                    serde_json::to_string_pretty(&result.outputs)?
                );
                break;
            }
            a3s_flow::ExecutionState::Failed(msg) => {
                println!("\n✗ Flow failed: {}", msg);
                return Err(msg.into());
            }
            a3s_flow::ExecutionState::Terminated => {
                println!("\n⚠ Flow terminated");
                return Ok(());
            }
            _ => continue,
        }
    }
    // 6. Demonstrate context awareness
    println!("\n📝 Context Awareness Demo:");
    println!("  - The MCP node read 'conversation_id' from shared context");
    println!("  - The MCP node wrote 'last_mcp_call' to shared context");
    println!("  - Other nodes in the flow can access this shared state");

    Ok(())
}

fn main() {
    napi_build::setup();
}

//! Node.js bindings for a3s-flow workflow engine.
//!
//! This module provides Node.js bindings using napi-rs for the a3s-flow Rust library.

use std::collections::HashMap;
use std::sync::{Arc, OnceLock};

use a3s_flow::{
    ExecutionState as RustExecutionState, FlowEngine as RustFlowEngine, FlowEvent as RustFlowEvent,
    FlowResult as RustFlowResult, NodeRegistry as RustNodeRegistry,
};
use napi::bindgen_prelude::*;
use napi_derive::napi;
use serde_json::Value;
use tokio::runtime::Runtime;

// ── Tokio Runtime ─────────────────────────────────────────────────────────

static RUNTIME: OnceLock<Runtime> = OnceLock::new();

fn get_runtime() -> &'static Runtime {
    RUNTIME.get_or_init(|| {
        tokio::runtime::Builder::new_current_thread()
            .enable_all()
            .build()
            .expect("failed to create tokio runtime")
    })
}

// ── FlowResult ────────────────────────────────────────────────────────────

/// Result of a completed flow execution.
#[napi(object)]
#[derive(Clone, serde::Serialize)]
pub struct FlowResult {
    /// Unique ID for this execution run.
    pub execution_id: String,
    /// Per-node outputs, keyed by node ID.
    pub outputs: serde_json::Value,
    /// IDs of all nodes that were processed (executed or skipped).
    pub completed_nodes: Vec<String>,
    /// IDs of nodes whose run_if guard evaluated to false and were skipped.
    pub skipped_nodes: Vec<String>,
    /// Final snapshot of the shared mutable context after execution.
    pub context: serde_json::Value,
}

impl From<RustFlowResult> for FlowResult {
    fn from(result: RustFlowResult) -> Self {
        Self {
            execution_id: result.execution_id.to_string(),
            outputs: serde_json::to_value(&result.outputs).unwrap_or(Value::Null),
            completed_nodes: result.completed_nodes.into_iter().collect(),
            skipped_nodes: result.skipped_nodes.into_iter().collect(),
            context: serde_json::to_value(&result.context).unwrap_or(Value::Null),
        }
    }
}

// ── ExecutionState ────────────────────────────────────────────────────────

/// Snapshot of a workflow execution's current lifecycle state.
#[napi(object)]
#[derive(Clone)]
pub struct ExecutionState {
    /// Status: "running", "paused", "completed", "failed", or "terminated"
    pub status: String,
    /// Result (only present when status is "completed")
    pub result: Option<FlowResult>,
    /// Error message (only present when status is "failed")
    pub error: Option<String>,
}

impl From<RustExecutionState> for ExecutionState {
    fn from(state: RustExecutionState) -> Self {
        match state {
            RustExecutionState::Running => Self {
                status: "running".to_string(),
                result: None,
                error: None,
            },
            RustExecutionState::Paused => Self {
                status: "paused".to_string(),
                result: None,
                error: None,
            },
            RustExecutionState::Completed(result) => Self {
                status: "completed".to_string(),
                result: Some(result.into()),
                error: None,
            },
            RustExecutionState::Failed(msg) => Self {
                status: "failed".to_string(),
                result: None,
                error: Some(msg),
            },
            RustExecutionState::Terminated => Self {
                status: "terminated".to_string(),
                result: None,
                error: None,
            },
        }
    }
}

// ── FlowEvent ─────────────────────────────────────────────────────────────

/// Event emitted during flow execution.
#[napi(object)]
#[derive(Clone)]
pub struct FlowEvent {
    /// Event type: "flow_started", "node_started", "node_completed", etc.
    #[napi(js_name = "eventType")]
    pub event_type: String,
    /// Execution ID
    #[napi(js_name = "executionId")]
    pub execution_id: String,
    /// Node ID (only present for node events)
    #[napi(js_name = "nodeId")]
    pub node_id: Option<String>,
    /// Output (only present for node_completed and flow_completed events)
    pub output: Option<serde_json::Value>,
    /// Error message (only present for node_failed and flow_failed events)
    pub error: Option<String>,
}

impl From<RustFlowEvent> for FlowEvent {
    fn from(event: RustFlowEvent) -> Self {
        match event {
            RustFlowEvent::FlowStarted { execution_id } => Self {
                event_type: "flow_started".to_string(),
                execution_id: execution_id.to_string(),
                node_id: None,
                output: None,
                error: None,
            },
            RustFlowEvent::NodeStarted {
                execution_id,
                node_id,
                node_type: _,
            } => Self {
                event_type: "node_started".to_string(),
                execution_id: execution_id.to_string(),
                node_id: Some(node_id),
                output: None,
                error: None,
            },
            RustFlowEvent::NodeCompleted {
                execution_id,
                node_id,
                output,
            } => Self {
                event_type: "node_completed".to_string(),
                execution_id: execution_id.to_string(),
                node_id: Some(node_id),
                output: Some(output),
                error: None,
            },
            RustFlowEvent::NodeSkipped {
                execution_id,
                node_id,
            } => Self {
                event_type: "node_skipped".to_string(),
                execution_id: execution_id.to_string(),
                node_id: Some(node_id),
                output: None,
                error: None,
            },
            RustFlowEvent::NodeFailed {
                execution_id,
                node_id,
                reason,
            } => Self {
                event_type: "node_failed".to_string(),
                execution_id: execution_id.to_string(),
                node_id: Some(node_id),
                output: None,
                error: Some(reason),
            },
            RustFlowEvent::FlowCompleted {
                execution_id,
                result,
            } => Self {
                event_type: "flow_completed".to_string(),
                execution_id: execution_id.to_string(),
                node_id: None,
                output: Some(
                    serde_json::to_value(&FlowResult::from(result)).unwrap_or(Value::Null),
                ),
                error: None,
            },
            RustFlowEvent::FlowFailed {
                execution_id,
                reason,
            } => Self {
                event_type: "flow_failed".to_string(),
                execution_id: execution_id.to_string(),
                node_id: None,
                output: None,
                error: Some(reason),
            },
            RustFlowEvent::FlowTerminated { execution_id } => Self {
                event_type: "flow_terminated".to_string(),
                execution_id: execution_id.to_string(),
                node_id: None,
                output: None,
                error: None,
            },
        }
    }
}

// ── FlowEngine ────────────────────────────────────────────────────────────

/// Workflow engine for managing flow executions.
#[napi]
pub struct FlowEngine {
    inner: Arc<RustFlowEngine>,
}

#[napi]
impl FlowEngine {
    /// Create a new flow engine with default built-in nodes.
    #[napi(constructor)]
    pub fn new() -> Self {
        let registry = RustNodeRegistry::with_defaults();
        Self {
            inner: Arc::new(RustFlowEngine::new(registry)),
        }
    }

    /// Start a new flow execution.
    ///
    /// @param definition - Flow definition with "nodes" and "edges"
    /// @param variables - Initial variables (optional)
    /// @returns Execution ID as a string
    #[napi]
    pub async fn start(
        &self,
        definition: serde_json::Value,
        variables: Option<serde_json::Value>,
    ) -> Result<String> {
        let vars = if let Some(v) = variables {
            serde_json::from_value::<HashMap<String, Value>>(v)
                .map_err(|e| Error::from_reason(format!("Invalid variables: {}", e)))?
        } else {
            HashMap::new()
        };

        let inner = Arc::clone(&self.inner);
        let id = inner
            .start(&definition, vars)
            .await
            .map_err(|e| Error::from_reason(format!("Failed to start flow: {}", e)))?;

        Ok(id.to_string())
    }

    /// Pause a running flow execution.
    ///
    /// @param executionId - Execution ID as a string
    #[napi]
    pub async fn pause(&self, execution_id: String) -> Result<()> {
        let id = execution_id
            .parse()
            .map_err(|e| Error::from_reason(format!("Invalid UUID: {}", e)))?;

        let inner = Arc::clone(&self.inner);
        inner
            .pause(id)
            .await
            .map_err(|e| Error::from_reason(format!("Failed to pause flow: {}", e)))?;

        Ok(())
    }

    /// Resume a paused flow execution.
    ///
    /// @param executionId - Execution ID as a string
    #[napi]
    pub async fn resume(&self, execution_id: String) -> Result<()> {
        let id = execution_id
            .parse()
            .map_err(|e| Error::from_reason(format!("Invalid UUID: {}", e)))?;

        let inner = Arc::clone(&self.inner);
        inner
            .resume(id)
            .await
            .map_err(|e| Error::from_reason(format!("Failed to resume flow: {}", e)))?;

        Ok(())
    }

    /// Terminate a running flow execution.
    ///
    /// @param executionId - Execution ID as a string
    #[napi]
    pub async fn terminate(&self, execution_id: String) -> Result<()> {
        let id = execution_id
            .parse()
            .map_err(|e| Error::from_reason(format!("Invalid UUID: {}", e)))?;

        let inner = Arc::clone(&self.inner);
        inner
            .terminate(id)
            .await
            .map_err(|e| Error::from_reason(format!("Failed to terminate flow: {}", e)))?;

        Ok(())
    }

    /// Get the current state of a flow execution.
    ///
    /// @param executionId - Execution ID as a string
    /// @returns ExecutionState object
    #[napi]
    pub async fn state(&self, execution_id: String) -> Result<ExecutionState> {
        let id = execution_id
            .parse()
            .map_err(|e| Error::from_reason(format!("Invalid UUID: {}", e)))?;

        let inner = Arc::clone(&self.inner);
        let state = inner
            .state(id)
            .await
            .map_err(|e| Error::from_reason(format!("Failed to get flow state: {}", e)))?;

        Ok(state.into())
    }

    /// List all registered node types.
    ///
    /// @returns Array of node type strings
    #[napi]
    pub fn node_types(&self) -> Vec<String> {
        self.inner.node_types()
    }
}

//! Python bindings for a3s-flow workflow engine.
//!
//! This module provides Python bindings using PyO3 for the a3s-flow Rust library.

use std::collections::HashMap;
use std::sync::{Arc, OnceLock};

use ::a3s_flow as flow_core;
use flow_core::{
    ExecutionState as RustExecutionState, FlowEngine as RustFlowEngine,
    FlowEvent as RustFlowEvent, FlowResult as RustFlowResult, NodeRegistry as RustNodeRegistry,
};
use pyo3::exceptions::{PyRuntimeError, PyValueError};
use pyo3::prelude::*;
use pyo3::types::{PyDict, PyList};
use serde_json::Value;
use tokio::runtime::Runtime;

// ── Tokio Runtime ─────────────────────────────────────────────────────────

static RUNTIME: OnceLock<Runtime> = OnceLock::new();

fn get_runtime() -> &'static Runtime {
    RUNTIME.get_or_init(|| {
        let cores = std::thread::available_parallelism()
            .map(|n| n.get())
            .unwrap_or(4);
        tokio::runtime::Builder::new_multi_thread()
            .worker_threads(cores * 2)
            .max_blocking_threads(512)
            .enable_all()
            .build()
            .expect("failed to create tokio runtime")
    })
}

// ── FlowResult ────────────────────────────────────────────────────────────

/// Result of a completed flow execution.
#[pyclass(name = "FlowResult")]
pub struct PyFlowResult {
    #[pyo3(get)]
    pub execution_id: String,
    #[pyo3(get)]
    pub outputs: Py<PyDict>,
    #[pyo3(get)]
    pub completed_nodes: Py<PyList>,
    #[pyo3(get)]
    pub skipped_nodes: Py<PyList>,
    #[pyo3(get)]
    pub context: Py<PyDict>,
}

impl PyFlowResult {
    fn from_rust(result: RustFlowResult, py: Python) -> PyResult<Self> {
        let outputs = PyDict::new_bound(py);
        for (k, v) in result.outputs {
            let py_val = json_to_py(py, &v)?;
            outputs.set_item(k, py_val)?;
        }

        let completed_nodes = PyList::new_bound(py, result.completed_nodes.iter());
        let skipped_nodes = PyList::new_bound(py, result.skipped_nodes.iter());

        let context = PyDict::new(py);
        for (k, v) in result.context {
            let py_val = json_to_py(py, &v)?;
            context.set_item(k, py_val)?;
        }

        Ok(Self {
            execution_id: result.execution_id.to_string(),
            outputs: outputs.unbind(),
            completed_nodes: completed_nodes.unbind(),
            skipped_nodes: skipped_nodes.unbind(),
            context: context.unbind(),
        })
    }
}

// ── ExecutionState ────────────────────────────────────────────────────────

/// Snapshot of a workflow execution's current lifecycle state.
#[pyclass(name = "ExecutionState")]
pub struct PyExecutionState {
    #[pyo3(get)]
    pub status: String,
    #[pyo3(get)]
    pub result: Option<Py<PyFlowResult>>,
    #[pyo3(get)]
    pub error: Option<String>,
}

impl PyExecutionState {
    fn from_rust(state: RustExecutionState, py: Python) -> PyResult<Self> {
        match state {
            RustExecutionState::Running => Ok(Self {
                status: "running".to_string(),
                result: None,
                error: None,
            }),
            RustExecutionState::Paused => Ok(Self {
                status: "paused".to_string(),
                result: None,
                error: None,
            }),
            RustExecutionState::Completed(result) => Ok(Self {
                status: "completed".to_string(),
                result: Some(Py::new(py, PyFlowResult::from_rust(result, py)?)?),
                error: None,
            }),
            RustExecutionState::Failed(msg) => Ok(Self {
                status: "failed".to_string(),
                result: None,
                error: Some(msg),
            }),
            RustExecutionState::Terminated => Ok(Self {
                status: "terminated".to_string(),
                result: None,
                error: None,
            }),
        }
    }
}

// ── FlowEvent ─────────────────────────────────────────────────────────────

/// Event emitted during flow execution.
#[pyclass(name = "FlowEvent")]
pub struct PyFlowEvent {
    #[pyo3(get)]
    pub event_type: String,
    #[pyo3(get)]
    pub execution_id: String,
    #[pyo3(get)]
    pub node_id: Option<String>,
    #[pyo3(get)]
    pub output: Option<Py<PyAny>>,
    #[pyo3(get)]
    pub error: Option<String>,
}

impl PyFlowEvent {
    fn from_rust(event: RustFlowEvent, py: Python) -> PyResult<Self> {
        match event {
            RustFlowEvent::FlowStarted { execution_id } => Ok(Self {
                event_type: "flow_started".to_string(),
                execution_id: execution_id.to_string(),
                node_id: None,
                output: None,
                error: None,
            }),
            RustFlowEvent::NodeStarted {
                execution_id,
                node_id,
                node_type: _,
            } => Ok(Self {
                event_type: "node_started".to_string(),
                execution_id: execution_id.to_string(),
                node_id: Some(node_id),
                output: None,
                error: None,
            }),
            RustFlowEvent::NodeCompleted {
                execution_id,
                node_id,
                output,
            } => Ok(Self {
                event_type: "node_completed".to_string(),
                execution_id: execution_id.to_string(),
                node_id: Some(node_id),
                output: Some(json_to_py(py, &output)?),
                error: None,
            }),
            RustFlowEvent::NodeSkipped {
                execution_id,
                node_id,
            } => Ok(Self {
                event_type: "node_skipped".to_string(),
                execution_id: execution_id.to_string(),
                node_id: Some(node_id),
                output: None,
                error: None,
            }),
            RustFlowEvent::NodeFailed {
                execution_id,
                node_id,
                reason,
            } => Ok(Self {
                event_type: "node_failed".to_string(),
                execution_id: execution_id.to_string(),
                node_id: Some(node_id),
                output: None,
                error: Some(reason),
            }),
            RustFlowEvent::FlowCompleted {
                execution_id,
                result,
            } => Ok(Self {
                event_type: "flow_completed".to_string(),
                execution_id: execution_id.to_string(),
                node_id: None,
                output: Some(Py::new(py, PyFlowResult::from_rust(result, py)?)?.into_any()),
                error: None,
            }),
            RustFlowEvent::FlowFailed {
                execution_id,
                reason,
            } => Ok(Self {
                event_type: "flow_failed".to_string(),
                execution_id: execution_id.to_string(),
                node_id: None,
                output: None,
                error: Some(reason),
            }),
            RustFlowEvent::FlowTerminated { execution_id } => Ok(Self {
                event_type: "flow_terminated".to_string(),
                execution_id: execution_id.to_string(),
                node_id: None,
                output: None,
                error: None,
            }),
        }
    }
}

// ── FlowEngine ────────────────────────────────────────────────────────────

/// Workflow engine for managing flow executions.
#[pyclass(name = "FlowEngine")]
pub struct PyFlowEngine {
    inner: Arc<RustFlowEngine>,
}

#[pymethods]
impl PyFlowEngine {
    /// Create a new flow engine with default built-in nodes.
    #[new]
    fn new() -> Self {
        let registry = RustNodeRegistry::with_defaults();
        Self {
            inner: Arc::new(RustFlowEngine::new(registry)),
        }
    }

    /// Start a new flow execution.
    ///
    /// Args:
    ///     definition: Flow definition as a dict with "nodes" and "edges"
    ///     variables: Initial variables as a dict (optional)
    ///
    /// Returns:
    ///     Execution ID as a string
    fn start(
        &self,
        py: Python,
        definition: &Bound<PyDict>,
        variables: Option<&Bound<PyDict>>,
    ) -> PyResult<String> {
        let def_json = py_to_json(py, definition.as_any())?;
        let vars = if let Some(v) = variables {
            py_dict_to_hashmap(py, v)?
        } else {
            HashMap::new()
        };

        let inner = Arc::clone(&self.inner);
        let result = get_runtime().block_on(async move { inner.start(&def_json, vars).await });

        match result {
            Ok(id) => Ok(id.to_string()),
            Err(e) => Err(PyRuntimeError::new_err(format!("Failed to start flow: {}", e))),
        }
    }

    /// Pause a running flow execution.
    ///
    /// Args:
    ///     execution_id: Execution ID as a string
    fn pause(&self, execution_id: &str) -> PyResult<()> {
        let id = parse_uuid(execution_id)?;
        let inner = Arc::clone(&self.inner);
        let result = get_runtime().block_on(async move { inner.pause(id).await });

        match result {
            Ok(()) => Ok(()),
            Err(e) => Err(PyRuntimeError::new_err(format!("Failed to pause flow: {}", e))),
        }
    }

    /// Resume a paused flow execution.
    ///
    /// Args:
    ///     execution_id: Execution ID as a string
    fn resume(&self, execution_id: &str) -> PyResult<()> {
        let id = parse_uuid(execution_id)?;
        let inner = Arc::clone(&self.inner);
        let result = get_runtime().block_on(async move { inner.resume(id).await });

        match result {
            Ok(()) => Ok(()),
            Err(e) => Err(PyRuntimeError::new_err(format!("Failed to resume flow: {}", e))),
        }
    }

    /// Terminate a running flow execution.
    ///
    /// Args:
    ///     execution_id: Execution ID as a string
    fn terminate(&self, execution_id: &str) -> PyResult<()> {
        let id = parse_uuid(execution_id)?;
        let inner = Arc::clone(&self.inner);
        let result = get_runtime().block_on(async move { inner.terminate(id).await });

        match result {
            Ok(()) => Ok(()),
            Err(e) => Err(PyRuntimeError::new_err(format!(
                "Failed to terminate flow: {}",
                e
            ))),
        }
    }

    /// Get the current state of a flow execution.
    ///
    /// Args:
    ///     execution_id: Execution ID as a string
    ///
    /// Returns:
    ///     ExecutionState object
    fn state(&self, py: Python, execution_id: &str) -> PyResult<PyExecutionState> {
        let id = parse_uuid(execution_id)?;
        let inner = Arc::clone(&self.inner);
        let result = get_runtime().block_on(async move { inner.state(id).await });

        match result {
            Ok(state) => PyExecutionState::from_rust(state, py),
            Err(e) => Err(PyRuntimeError::new_err(format!(
                "Failed to get flow state: {}",
                e
            ))),
        }
    }

    /// List all registered node types.
    ///
    /// Returns:
    ///     List of node type strings
    fn node_types(&self) -> Vec<String> {
        self.inner.node_types()
    }
}

// ── Helper Functions ──────────────────────────────────────────────────────

fn parse_uuid(s: &str) -> PyResult<uuid::Uuid> {
    s.parse()
        .map_err(|e| PyValueError::new_err(format!("Invalid UUID: {}", e)))
}

fn py_to_json(py: Python, obj: &Bound<PyAny>) -> PyResult<Value> {
    let json_str = obj.call_method0("__str__")?;
    let json_str: String = json_str.extract()?;
    serde_json::from_str(&json_str)
        .map_err(|e| PyValueError::new_err(format!("Failed to convert to JSON: {}", e)))
}

fn json_to_py(py: Python, value: &Value) -> PyResult<Py<PyAny>> {
    match value {
        Value::Null => Ok(py.None()),
        Value::Bool(b) => Ok(b.into_py(py)),
        Value::Number(n) => {
            if let Some(i) = n.as_i64() {
                Ok(i.into_py(py))
            } else if let Some(f) = n.as_f64() {
                Ok(f.into_py(py))
            } else {
                Ok(py.None())
            }
        }
        Value::String(s) => Ok(s.into_py(py)),
        Value::Array(arr) => {
            let list = PyList::empty_bound(py);
            for item in arr {
                list.append(json_to_py(py, item)?)?;
            }
            Ok(list.into_any().unbind())
        }
        Value::Object(obj) => {
            let dict = PyDict::new_bound(py);
            for (k, v) in obj {
                dict.set_item(k, json_to_py(py, v)?)?;
            }
            Ok(dict.into_any().unbind())
        }
    }
}

fn py_dict_to_hashmap(py: Python, dict: &Bound<PyDict>) -> PyResult<HashMap<String, Value>> {
    let mut map = HashMap::new();
    for (k, v) in dict.iter() {
        let key: String = k.extract()?;
        let value = py_to_json(py, &v)?;
        map.insert(key, value);
    }
    Ok(map)
}

// ── Module Definition ─────────────────────────────────────────────────────

#[pymodule]
fn a3s_flow(m: &Bound<PyModule>) -> PyResult<()> {
    m.add_class::<PyFlowEngine>()?;
    m.add_class::<PyFlowResult>()?;
    m.add_class::<PyExecutionState>()?;
    m.add_class::<PyFlowEvent>()?;
    Ok(())
}

//! Structured capability discovery for `a3s-flow`.
//!
//! This module provides a transport-friendly view of the engine's built-in and
//! custom node catalog so higher layers can expose progressive discovery APIs
//! without hard-coding node metadata.

use serde::{Deserialize, Serialize};

use crate::registry::NodeDescriptor;

/// Stable capabilities document for a `FlowEngine` instance.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct FlowCapabilities {
    /// Schema/version marker for downstream clients.
    pub version: String,
    /// Whether clients should progressively expand into finer-grained
    /// capabilities instead of assuming a fixed surface.
    pub progressive_disclosure: bool,
    /// Short human-readable summary of the current engine capability set.
    pub summary: String,
    /// Structured node catalog, sorted by `node_type`.
    pub nodes: Vec<NodeDescriptor>,
}

impl FlowCapabilities {
    /// Build a capabilities document from a node catalog.
    pub fn from_nodes(nodes: Vec<NodeDescriptor>) -> Self {
        Self {
            version: "2026-03-22".to_string(),
            progressive_disclosure: true,
            summary: "A3S Flow exposes a discoverable catalog of workflow node capabilities."
                .to_string(),
            nodes,
        }
    }
}

//! Condition types shared by `run_if` (in [`NodeDef`]) and the `"if-else"` built-in node.
//!
//! - [`Condition`] — single comparison (`from`, `path`, `op`, `value`)
//! - [`Case`] — named branch with one or more conditions joined by [`LogicalOp`]
//!
//! The evaluation logic lives here once and is reused by the runner and nodes.
//!
//! [`NodeDef`]: crate::graph::NodeDef

use std::cmp::Ordering;
use std::collections::{HashMap, HashSet};

use serde::{Deserialize, Serialize};
use serde_json::Value;

// ── Operators ──────────────────────────────────────────────────────────────

/// Comparison operator for a [`Condition`].
/// Mirrors Dify's 21-operator set.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum CondOp {
    /// Numeric equal (`==`)
    Eq,
    /// Numeric not equal (`!=`)
    Ne,
    /// Greater than (`>`, numbers only)
    Gt,
    /// Less than (`<`, numbers only)
    Lt,
    /// Greater than or equal (`>=`, numbers only)
    Gte,
    /// Less than or equal (`<=`, numbers only)
    Lte,
    /// Substring / element membership: `actual.contains(value)`
    Contains,
    /// String starts with prefix
    StartWith,
    /// String ends with suffix
    EndWith,
    /// Type-agnostic equality (JSON `==`)
    Is,
    /// Type-agnostic inequality (JSON `!=`)
    IsNot,
    /// Value is null, empty string, empty array, or empty object
    Empty,
    /// Value is not null, empty string, empty array, or empty object
    NotEmpty,
    /// Value is JSON null
    IsNull,
    /// Value is not JSON null
    IsNotNull,
    /// Value is a member of the expected array
    In,
    /// Value is not a member of the expected array
    NotIn,
    /// All elements in `actual` array satisfy the condition (recursive `value` check)
    AllOf,
    /// The field/path exists in the source object
    Exists,
    /// The field/path does not exist in the source object
    NotExists,
}

/// Logical operator combining multiple conditions inside a [`Case`].
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum LogicalOp {
    /// All conditions must be true (default, matches Dify default).
    #[default]
    And,
    /// At least one condition must be true.
    Or,
}

// ── Condition ──────────────────────────────────────────────────────────────

/// A single comparison against an upstream node's output.
///
/// Used in two places:
/// - `run_if` on a [`NodeDef`] — guard that skips the node when false
/// - inside a [`Case`] in the `"if-else"` node config
///
/// [`NodeDef`]: crate::graph::NodeDef
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Condition {
    /// ID of the upstream node whose output to inspect.
    pub from: String,
    /// Dot-separated path into the upstream output (e.g. `"status"`, `"data.count"`).
    /// Use `""` to compare the root value.
    pub path: String,
    /// Comparison operator.
    pub op: CondOp,
    /// Right-hand side value.
    pub value: Value,
}

impl Condition {
    /// Evaluate against the full output map, respecting the skipped set.
    ///
    /// Returns `false` when the source node was skipped, is missing, the path
    /// does not resolve, or the comparison fails.
    pub fn evaluate(&self, outputs: &HashMap<String, Value>, skipped: &HashSet<String>) -> bool {
        if skipped.contains(&self.from) {
            return false;
        }
        let from_output = match outputs.get(&self.from) {
            Some(v) => v,
            None => return false,
        };
        self.evaluate_on_value(from_output)
    }

    /// Evaluate directly against a single upstream output value.
    ///
    /// Used by the `"if-else"` node, which already has the value in `ctx.inputs`.
    pub fn evaluate_on_value(&self, from_output: &Value) -> bool {
        if from_output.is_null() {
            return false;
        }
        let actual = match get_path(from_output, &self.path) {
            Some(v) => v,
            None => return false,
        };
        compare(actual, &self.op, &self.value)
    }
}

// ── Case ───────────────────────────────────────────────────────────────────

/// A named branch inside an `"if-else"` node.
///
/// A case is satisfied when its conditions evaluate to true according to
/// `logical_operator`. Cases are tested in order; the first match wins.
///
/// # Example
///
/// ```json
/// {
///   "id": "is_ok",
///   "logical_operator": "and",
///   "conditions": [
///     { "from": "fetch", "path": "status", "op": "eq", "value": 200 }
///   ]
/// }
/// ```
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Case {
    /// Branch identifier — returned as `"branch"` in the node output.
    pub id: String,
    /// How multiple conditions are combined (default: `"and"`).
    #[serde(default)]
    pub logical_operator: LogicalOp,
    /// Conditions that must hold for this case to match.
    pub conditions: Vec<Condition>,
}

impl Case {
    /// Evaluate all conditions against `inputs`, combining with `logical_operator`.
    ///
    /// Returns `false` for an empty conditions list.
    pub fn evaluate(&self, inputs: &HashMap<String, Value>) -> bool {
        if self.conditions.is_empty() {
            return false;
        }
        let results = self.conditions.iter().map(|cond| {
            inputs
                .get(&cond.from)
                .map(|v| cond.evaluate_on_value(v))
                .unwrap_or(false)
        });
        match self.logical_operator {
            LogicalOp::And => results.into_iter().all(|b| b),
            LogicalOp::Or => results.into_iter().any(|b| b),
        }
    }
}

// ── Helpers ──────��─────────────────────────────────────────────────────────

/// Navigate a dot-separated path into a JSON value.
///
/// Returns `None` if any key is missing. Empty path returns the root.
pub(crate) fn get_path<'a>(value: &'a Value, path: &str) -> Option<&'a Value> {
    if path.is_empty() {
        return Some(value);
    }
    let mut current = value;
    for key in path.split('.') {
        current = current.get(key)?;
    }
    Some(current)
}

fn compare(actual: &Value, op: &CondOp, expected: &Value) -> bool {
    match op {
        CondOp::Eq => actual == expected,
        CondOp::Ne => actual != expected,
        CondOp::Gt => numeric_cmp(actual, expected) == Some(Ordering::Greater),
        CondOp::Lt => numeric_cmp(actual, expected) == Some(Ordering::Less),
        CondOp::Gte => matches!(
            numeric_cmp(actual, expected),
            Some(Ordering::Greater | Ordering::Equal)
        ),
        CondOp::Lte => matches!(
            numeric_cmp(actual, expected),
            Some(Ordering::Less | Ordering::Equal)
        ),
        CondOp::Contains => match (actual, expected) {
            (Value::String(s), Value::String(sub)) => s.contains(sub.as_str()),
            (Value::Array(arr), v) => arr.contains(v),
            _ => false,
        },
        CondOp::StartWith => match (actual, expected) {
            (Value::String(s), Value::String(prefix)) => s.starts_with(prefix.as_str()),
            _ => false,
        },
        CondOp::EndWith => match (actual, expected) {
            (Value::String(s), Value::String(suffix)) => s.ends_with(suffix.as_str()),
            _ => false,
        },
        CondOp::Is => json_type_equal(actual, expected),
        CondOp::IsNot => !json_type_equal(actual, expected),
        CondOp::Empty => is_empty(actual),
        CondOp::NotEmpty => !is_empty(actual),
        CondOp::IsNull => actual.is_null(),
        CondOp::IsNotNull => !actual.is_null(),
        CondOp::In => array_contains(expected, actual),
        CondOp::NotIn => !array_contains(expected, actual),
        CondOp::AllOf => all_elements_match(actual, expected),
        CondOp::Exists => !actual.is_null(),
        CondOp::NotExists => actual.is_null(),
    }
}

/// Check type-agnostic equality (JSON `==` semantics without number coercion).
fn json_type_equal(a: &Value, b: &Value) -> bool {
    match (a, b) {
        (Value::Null, Value::Null) => true,
        (Value::Bool(a), Value::Bool(b)) => a == b,
        (Value::Number(a), Value::Number(b)) => a == b,
        (Value::String(a), Value::String(b)) => a == b,
        (Value::Array(a), Value::Array(b)) => a == b,
        (Value::Object(a), Value::Object(b)) => a == b,
        _ => false,
    }
}

/// Check if a value is null, empty string, empty array, or empty object.
fn is_empty(v: &Value) -> bool {
    match v {
        Value::Null => true,
        Value::String(s) => s.is_empty(),
        Value::Array(arr) => arr.is_empty(),
        Value::Object(obj) => obj.is_empty(),
        _ => false,
    }
}

/// Check if `array` (expected) contains `item` (actual).
fn array_contains(array: &Value, item: &Value) -> bool {
    match array {
        Value::Array(arr) => arr.contains(item),
        _ => false,
    }
}

/// Check if all elements in `actual` array satisfy the condition (recursive check with `expected` value).
/// This is used for `AllOf` operator where actual is an array and expected is the value to check against each element.
fn all_elements_match(actual: &Value, expected: &Value) -> bool {
    match actual {
        Value::Array(arr) => arr
            .iter()
            .all(|elem| compare(elem, &CondOp::Contains, expected)),
        _ => false,
    }
}

fn numeric_cmp(a: &Value, b: &Value) -> Option<Ordering> {
    a.as_f64()?.partial_cmp(&b.as_f64()?)
}

// ── Tests ──────────────────────────────────────────────────────────────────

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    fn outputs(pairs: &[(&str, Value)]) -> HashMap<String, Value> {
        pairs
            .iter()
            .map(|(k, v)| (k.to_string(), v.clone()))
            .collect()
    }

    fn inputs(pairs: &[(&str, Value)]) -> HashMap<String, Value> {
        outputs(pairs)
    }

    #[test]
    fn condition_eq_passes() {
        let cond = Condition {
            from: "a".into(),
            path: "status".into(),
            op: CondOp::Eq,
            value: json!(200),
        };
        assert!(cond.evaluate(&outputs(&[("a", json!({"status": 200}))]), &HashSet::new()));
    }

    #[test]
    fn condition_eq_fails() {
        let cond = Condition {
            from: "a".into(),
            path: "status".into(),
            op: CondOp::Eq,
            value: json!(200),
        };
        assert!(!cond.evaluate(&outputs(&[("a", json!({"status": 404}))]), &HashSet::new()));
    }

    #[test]
    fn skipped_upstream_propagates() {
        let cond = Condition {
            from: "a".into(),
            path: "".into(),
            op: CondOp::Eq,
            value: json!(true),
        };
        let mut skipped = HashSet::new();
        skipped.insert("a".to_string());
        assert!(!cond.evaluate(&outputs(&[("a", json!(null))]), &skipped));
    }

    #[test]
    fn null_upstream_returns_false() {
        let cond = Condition {
            from: "a".into(),
            path: "x".into(),
            op: CondOp::Eq,
            value: json!(1),
        };
        assert!(!cond.evaluate_on_value(&json!(null)));
    }

    #[test]
    fn gt_numeric() {
        let cond = Condition {
            from: "a".into(),
            path: "count".into(),
            op: CondOp::Gt,
            value: json!(5),
        };
        assert!(cond.evaluate(&outputs(&[("a", json!({"count": 10}))]), &HashSet::new()));
    }

    #[test]
    fn contains_string() {
        let cond = Condition {
            from: "a".into(),
            path: "msg".into(),
            op: CondOp::Contains,
            value: json!("hello"),
        };
        assert!(cond.evaluate(
            &outputs(&[("a", json!({"msg": "say hello world"}))]),
            &HashSet::new()
        ));
    }

    #[test]
    fn case_and_all_pass() {
        let case = Case {
            id: "ok".into(),
            logical_operator: LogicalOp::And,
            conditions: vec![
                Condition {
                    from: "a".into(),
                    path: "x".into(),
                    op: CondOp::Eq,
                    value: json!(1),
                },
                Condition {
                    from: "a".into(),
                    path: "y".into(),
                    op: CondOp::Eq,
                    value: json!(2),
                },
            ],
        };
        assert!(case.evaluate(&inputs(&[("a", json!({"x": 1, "y": 2}))])));
    }

    #[test]
    fn case_and_one_fails() {
        let case = Case {
            id: "ok".into(),
            logical_operator: LogicalOp::And,
            conditions: vec![
                Condition {
                    from: "a".into(),
                    path: "x".into(),
                    op: CondOp::Eq,
                    value: json!(1),
                },
                Condition {
                    from: "a".into(),
                    path: "y".into(),
                    op: CondOp::Eq,
                    value: json!(99),
                },
            ],
        };
        assert!(!case.evaluate(&inputs(&[("a", json!({"x": 1, "y": 2}))])));
    }

    #[test]
    fn case_or_one_passes() {
        let case = Case {
            id: "ok".into(),
            logical_operator: LogicalOp::Or,
            conditions: vec![
                Condition {
                    from: "a".into(),
                    path: "x".into(),
                    op: CondOp::Eq,
                    value: json!(99),
                },
                Condition {
                    from: "a".into(),
                    path: "y".into(),
                    op: CondOp::Eq,
                    value: json!(2),
                },
            ],
        };
        assert!(case.evaluate(&inputs(&[("a", json!({"x": 1, "y": 2}))])));
    }

    #[test]
    fn case_empty_conditions_returns_false() {
        let case = Case {
            id: "ok".into(),
            logical_operator: LogicalOp::And,
            conditions: vec![],
        };
        assert!(!case.evaluate(&inputs(&[])));
    }
}

//! [`FlowEngine`] — the central API for managing workflow executions.
//!
//! `FlowEngine` wraps a [`NodeRegistry`] and an in-memory execution map.
//! It is the recommended entry point for applications that need lifecycle
//! control over running workflows.
//!
//! # Lifecycle
//!
//! ```text
//!                    ┌──────────┐
//!             start  │ Running  │ ←──────────── resume
//!           ────────►│          │
//!                    └────┬─────┘
//!               pause │   │ node error / all nodes done / terminate
//!                     ▼   ▼
//!                 ┌────────────┐   ┌───────────┐   ┌────────────┐
//!                 │   Paused   │   │ Completed │   │   Failed   │
//!                 └────────────┘   └───────────┘   └────────────┘
//!                                                  ┌────────────┐
//!                                                  │ Terminated │
//!                                                  └────────────┘
//! ```
//!
//! Pause takes effect at the **next wave boundary** — the current wave of
//! concurrently executing nodes runs to completion first. Terminate interrupts
//! the engine between or within waves and is reflected as soon as the runner
//! task observes the cancellation signal.

use std::collections::HashMap;
use std::sync::{Arc, RwLock as SyncRwLock};

use serde_json::Value;
use tokio::sync::{watch, RwLock};
use tokio_util::sync::CancellationToken;
use tracing::warn;
use uuid::Uuid;

use tokio::sync::broadcast;

use crate::capabilities::FlowCapabilities;
use crate::error::{FlowError, Result};
use crate::event::{ChannelEmitter, EventEmitter, FlowEvent, MulticastEmitter, NoopEventEmitter};
use crate::execution::{ExecutionHandle, ExecutionState};
use crate::flow_store::FlowStore;
use crate::graph::DagGraph;
use crate::node::Node;
use crate::registry::{NodeDescriptor, NodeRegistry};
use crate::runner::{FlowRunner, FlowSignal};
use crate::store::ExecutionStore;
use crate::validation::ValidationIssue;

/// Central entry point for managing workflow executions.
///
/// # Example
///
/// ```rust,no_run
/// use a3s_flow::{FlowEngine, NodeRegistry};
/// use serde_json::json;
/// use std::collections::HashMap;
///
/// #[tokio::main]
/// async fn main() -> a3s_flow::Result<()> {
///     let engine = FlowEngine::new(NodeRegistry::with_defaults());
///
///     // Query available node types.
///     println!("node types: {:?}", engine.node_types());
///
///     // Start a workflow and get its execution ID.
///     let definition = json!({
///         "nodes": [
///             { "id": "a", "type": "noop" },
///             { "id": "b", "type": "noop" }
///         ],
///         "edges": [{ "source": "a", "target": "b" }]
///     });
///     let id = engine.start(&definition, HashMap::new()).await?;
///
///     // Inspect state, pause, resume, or terminate.
///     println!("state: {:?}", engine.state(id).await?);
///     Ok(())
/// }
/// ```
pub struct FlowEngine {
    registry: Arc<SyncRwLock<NodeRegistry>>,
    executions: Arc<RwLock<HashMap<Uuid, ExecutionHandle>>>,
    /// Optional store — when set, completed results are automatically persisted.
    execution_store: Option<Arc<dyn ExecutionStore>>,
    /// Optional store — enables `start_named` to look up definitions by name.
    flow_store: Option<Arc<dyn FlowStore>>,
    /// Emitter passed to each runner; receives all node and flow lifecycle events.
    emitter: Arc<dyn EventEmitter>,
    /// When set, passed to every runner to cap per-wave node concurrency.
    max_concurrency: Option<usize>,
}

impl FlowEngine {
    /// Create a new engine with the given node registry.
    ///
    /// Uses [`NoopEventEmitter`] and no execution store by default. Use the
    /// builder methods [`with_execution_store`](Self::with_execution_store) and
    /// [`with_event_emitter`](Self::with_event_emitter) to customise behaviour.
    pub fn new(registry: NodeRegistry) -> Self {
        Self {
            registry: Arc::new(SyncRwLock::new(registry)),
            executions: Arc::new(RwLock::new(HashMap::new())),
            execution_store: None,
            flow_store: None,
            emitter: Arc::new(NoopEventEmitter),
            max_concurrency: None,
        }
    }

    /// Attach an execution store.
    ///
    /// When set, every successfully completed execution result is saved to the
    /// store automatically. Returns `self` for method chaining.
    pub fn with_execution_store(mut self, store: Arc<dyn ExecutionStore>) -> Self {
        self.execution_store = Some(store);
        self
    }

    /// Attach a flow definition store.
    ///
    /// Required for [`start_named`](Self::start_named). Allows any backend
    /// (in-memory, SQLite, remote API, …) by implementing [`FlowStore`].
    /// Returns `self` for method chaining.
    pub fn with_flow_store(mut self, store: Arc<dyn FlowStore>) -> Self {
        self.flow_store = Some(store);
        self
    }

    /// Attach a custom event emitter.
    ///
    /// The emitter is passed to every runner created by this engine and
    /// receives all node and flow lifecycle events. Returns `self` for chaining.
    pub fn with_event_emitter(mut self, emitter: Arc<dyn EventEmitter>) -> Self {
        self.emitter = emitter;
        self
    }

    /// Limit the number of nodes that may execute concurrently within a single
    /// wave across all executions started by this engine.
    ///
    /// Delegates to [`FlowRunner::with_max_concurrency`]. Returns `self` for chaining.
    pub fn with_max_concurrency(mut self, n: usize) -> Self {
        self.max_concurrency = Some(n);
        self
    }

    // ── Node type discovery ────────────────────────────────────────────────

    /// Return all registered node type strings, sorted alphabetically.
    ///
    /// Includes built-in types (e.g. `"noop"`) and any types registered via
    /// [`NodeRegistry::register`].
    pub fn node_types(&self) -> Vec<String> {
        self.registry.read().unwrap().list_types()
    }

    /// Return structured descriptors for all registered node types.
    ///
    /// This is the preferred discovery API for building UIs, skill pickers,
    /// and progressive capability endpoints on top of `a3s-flow`.
    pub fn node_descriptors(&self) -> Vec<NodeDescriptor> {
        self.registry.read().unwrap().list_descriptors()
    }

    /// Return a transport-friendly capabilities document for this engine.
    ///
    /// Higher layers can serialize this value directly as JSON for progressive
    /// discovery APIs.
    pub fn capabilities(&self) -> FlowCapabilities {
        FlowCapabilities::from_nodes(self.node_descriptors())
    }

    // ── Node type management ───────────────────────────────────────────────

    /// Register or replace a node type for future executions started by this engine.
    pub fn register_node_type(&self, node: Arc<dyn Node>) {
        self.registry.write().unwrap().register(node);
    }

    /// Register or replace a node type with explicit discovery metadata.
    pub fn register_node_type_with_descriptor(
        &self,
        node: Arc<dyn Node>,
        descriptor: NodeDescriptor,
    ) {
        self.registry
            .write()
            .unwrap()
            .register_with_descriptor(node, descriptor);
    }

    /// Remove a node type from this engine's registry.
    ///
    /// Returns `Ok(true)` if the node type existed and was removed, `Ok(false)`
    /// if it was not registered, or an error if the type is protected.
    ///
    /// Removal only affects future validations and executions. Already running
    /// executions keep using the registry snapshot captured when they were started.
    pub fn unregister_node_type(&self, node_type: &str) -> Result<bool> {
        self.registry.write().unwrap().unregister(node_type)
    }

    // ── Pre-flight validation ──────────────────────────────────────────────

    /// Validate a flow definition without executing it.
    ///
    /// Returns a list of [`ValidationIssue`]s describing structural problems.
    /// An empty list means the definition is valid and ready to run.
    ///
    /// The following checks are performed:
    /// - DAG structural validity: no cycles, no unknown edge references,
    ///   no duplicate node IDs, at least one node.
    /// - All node types are registered in the engine's [`NodeRegistry`].
    /// - Every `run_if.from` field references an existing node ID.
    ///
    /// ```rust
    /// use a3s_flow::{FlowEngine, NodeRegistry};
    /// use serde_json::json;
    ///
    /// let engine = FlowEngine::new(NodeRegistry::with_defaults());
    /// let def = json!({
    ///     "nodes": [
    ///         { "id": "a", "type": "noop" },
    ///         { "id": "b", "type": "unknown-type" }
    ///     ],
    ///     "edges": []
    /// });
    /// let issues = engine.validate(&def);
    /// assert_eq!(issues.len(), 1);
    /// assert!(issues[0].message.contains("unknown node type"));
    /// ```
    pub fn validate(&self, definition: &Value) -> Vec<ValidationIssue> {
        let mut issues = Vec::new();

        // Parse the DAG — catches cycle, unknown refs, duplicate IDs, empty flow.
        let dag = match DagGraph::from_json(definition) {
            Ok(dag) => dag,
            Err(e) => {
                issues.push(ValidationIssue {
                    node_id: None,
                    message: e.to_string(),
                });
                return issues;
            }
        };

        for node_def in dag.nodes_in_order() {
            // Check node type is registered.
            if self
                .registry
                .read()
                .unwrap()
                .get(&node_def.node_type)
                .is_err()
            {
                issues.push(ValidationIssue {
                    node_id: Some(node_def.id.clone()),
                    message: format!("unknown node type '{}'", node_def.node_type),
                });
            }

            // Check run_if.from references an existing node.
            if let Some(ref cond) = node_def.run_if {
                if !dag.nodes.contains_key(&cond.from) {
                    issues.push(ValidationIssue {
                        node_id: Some(node_def.id.clone()),
                        message: format!("run_if references unknown node '{}'", cond.from),
                    });
                }
            }
        }

        issues
    }

    // ── Execution lifecycle ────────────────────────────────────────────────

    /// Start a new workflow execution from a JSON DAG definition.
    ///
    /// The definition is parsed and validated synchronously. If valid, the
    /// execution is launched in a background Tokio task and the execution ID
    /// is returned immediately — the flow runs concurrently with the caller.
    ///
    /// # Errors
    ///
    /// Returns an error if the definition is invalid (cycle, unknown node ID,
    /// bad JSON, unregistered node type).
    pub async fn start(
        &self,
        definition: &Value,
        variables: HashMap<String, Value>,
    ) -> Result<Uuid> {
        let (id, _rx) = self.start_inner(definition, variables).await?;
        Ok(id)
    }

    /// Start a workflow and return a live event stream alongside the execution ID.
    ///
    /// The returned [`broadcast::Receiver<FlowEvent>`] is created **before** the
    /// execution task is spawned, guaranteeing that no events are missed —
    /// including `FlowStarted`. Multiple subscribers can be created by calling
    /// [`broadcast::Receiver::resubscribe`].
    ///
    /// The stream closes (returns `Err(RecvError::Closed)`) when the execution
    /// reaches a terminal state (`Completed`, `Failed`, or `Terminated`).
    ///
    /// If the engine also has a custom [`EventEmitter`] configured via
    /// [`with_event_emitter`](Self::with_event_emitter), both the emitter and
    /// the broadcast channel receive every event.
    ///
    /// # Example
    ///
    /// ```rust,no_run
    /// use a3s_flow::{FlowEngine, FlowEvent, NodeRegistry};
    /// use serde_json::json;
    /// use std::collections::HashMap;
    ///
    /// #[tokio::main]
    /// async fn main() -> a3s_flow::Result<()> {
    ///     let engine = FlowEngine::new(NodeRegistry::with_defaults());
    ///     let def = json!({
    ///         "nodes": [{ "id": "a", "type": "noop" }],
    ///         "edges": []
    ///     });
    ///
    ///     let (id, mut rx) = engine.start_streaming(&def, HashMap::new()).await?;
    ///
    ///     while let Ok(event) = rx.recv().await {
    ///         match event {
    ///             FlowEvent::NodeCompleted { node_id, .. } => println!("done: {node_id}"),
    ///             FlowEvent::FlowCompleted { .. } => break,
    ///             _ => {}
    ///         }
    ///     }
    ///     Ok(())
    /// }
    /// ```
    pub async fn start_streaming(
        &self,
        definition: &Value,
        variables: HashMap<String, Value>,
    ) -> Result<(Uuid, broadcast::Receiver<FlowEvent>)> {
        let (id, rx) = self.start_inner(definition, variables).await?;
        Ok((id, rx))
    }

    /// Subscribe to live events for an existing execution.
    ///
    /// The returned receiver attaches to the execution's dedicated broadcast
    /// channel. Events emitted before subscription are not replayed.
    pub async fn subscribe(&self, id: Uuid) -> Result<broadcast::Receiver<FlowEvent>> {
        let executions = self.executions.read().await;
        let handle = executions
            .get(&id)
            .ok_or(FlowError::ExecutionNotFound(id))?;
        let receiver = handle
            .event_tx
            .read()
            .unwrap()
            .as_ref()
            .map(|tx| tx.subscribe())
            .ok_or_else(|| FlowError::InvalidTransition {
                action: "subscribe".into(),
                from: "finished".into(),
            })?;
        Ok(receiver)
    }

    /// Internal start implementation shared by both `start` and
    /// `start_streaming`.
    async fn start_inner(
        &self,
        definition: &Value,
        variables: HashMap<String, Value>,
    ) -> Result<(Uuid, broadcast::Receiver<FlowEvent>)> {
        let dag = DagGraph::from_json(definition)?;
        let registry = self.registry.read().unwrap().clone();
        let (event_tx, event_rx) = broadcast::channel(256);
        let channel_emitter = Arc::new(ChannelEmitter::new(event_tx.clone()));
        let emitter: Arc<dyn EventEmitter> = Arc::new(MulticastEmitter {
            a: Arc::clone(&self.emitter),
            b: channel_emitter,
        });
        let mut runner = FlowRunner::new(dag, registry).with_event_emitter(emitter);
        if let Some(ref fs) = self.flow_store {
            runner = runner.with_flow_store(Arc::clone(fs));
        }
        if let Some(n) = self.max_concurrency {
            runner = runner.with_max_concurrency(n);
        }

        let execution_id = Uuid::new_v4();
        let cancel = CancellationToken::new();
        let (signal_tx, signal_rx) = watch::channel(FlowSignal::Run);
        let state = Arc::new(RwLock::new(ExecutionState::Running));
        let context: Arc<SyncRwLock<HashMap<String, Value>>> =
            Arc::new(SyncRwLock::new(HashMap::new()));
        let event_tx_handle = Arc::new(SyncRwLock::new(Some(event_tx)));

        let handle = ExecutionHandle {
            state: Arc::clone(&state),
            signal_tx,
            cancel: cancel.clone(),
            context: Arc::clone(&context),
            event_tx: Arc::clone(&event_tx_handle),
        };

        self.executions.write().await.insert(execution_id, handle);

        // Spawn the execution task; it updates state on terminal transitions.
        // Logging and event emission are handled by FlowRunner::run_seeded.
        let state_for_task = Arc::clone(&state);
        let event_tx_for_task = Arc::clone(&event_tx_handle);
        let execution_store = self.execution_store.clone();
        tokio::spawn(async move {
            match runner
                .run_controlled(execution_id, variables, signal_rx, cancel, context)
                .await
            {
                Ok(result) => {
                    // Persist the result if a store is configured.
                    if let Some(ref store) = execution_store {
                        if let Err(e) = store.save(&result).await {
                            warn!(%execution_id, error = %e, "failed to persist execution result");
                        }
                    }
                    *state_for_task.write().await = ExecutionState::Completed(result);
                }
                Err(FlowError::Terminated) => {
                    *state_for_task.write().await = ExecutionState::Terminated;
                }
                Err(e) => {
                    *state_for_task.write().await = ExecutionState::Failed(e.to_string());
                }
            }
            let _ = event_tx_for_task.write().unwrap().take();
        });

        Ok((execution_id, event_rx))
    }

    /// Start a workflow by loading its definition from the configured
    /// [`FlowStore`] by name.
    ///
    /// Equivalent to:
    /// ```rust,ignore
    /// let def = flow_store.load(name).await?.ok_or(...)?;
    /// engine.start(&def, variables).await
    /// ```
    ///
    /// # Errors
    ///
    /// - [`FlowError::Internal`] if no `FlowStore` was configured via
    ///   [`with_flow_store`](Self::with_flow_store).
    /// - [`FlowError::FlowNotFound`] if no definition exists under `name`.
    /// - Any error returned by [`start`](Self::start) (invalid definition, etc.).
    pub async fn start_named(&self, name: &str, variables: HashMap<String, Value>) -> Result<Uuid> {
        let store = self.flow_store.as_ref().ok_or_else(|| {
            FlowError::Internal("no FlowStore configured; call with_flow_store first".into())
        })?;

        let definition = store
            .load(name)
            .await?
            .ok_or_else(|| FlowError::FlowNotFound(name.to_string()))?;

        self.start(&definition, variables).await
    }

    /// Pause a running execution at the next wave boundary.
    ///
    /// Nodes in the **current wave** continue until they finish. No new wave
    /// starts until [`resume`](Self::resume) is called.
    ///
    /// # Errors
    ///
    /// - [`FlowError::ExecutionNotFound`] if the ID is unknown.
    /// - [`FlowError::InvalidTransition`] if the execution is not `Running`.
    pub async fn pause(&self, id: Uuid) -> Result<()> {
        let executions = self.executions.read().await;
        let handle = executions
            .get(&id)
            .ok_or(FlowError::ExecutionNotFound(id))?;

        let mut state = handle.state.write().await;
        match *state {
            ExecutionState::Running => {
                handle.signal_tx.send(FlowSignal::Pause).ok();
                *state = ExecutionState::Paused;
                Ok(())
            }
            ref s => Err(FlowError::InvalidTransition {
                action: "pause".into(),
                from: s.as_str().into(),
            }),
        }
    }

    /// Resume a paused execution.
    ///
    /// # Errors
    ///
    /// - [`FlowError::ExecutionNotFound`] if the ID is unknown.
    /// - [`FlowError::InvalidTransition`] if the execution is not `Paused`.
    pub async fn resume(&self, id: Uuid) -> Result<()> {
        let executions = self.executions.read().await;
        let handle = executions
            .get(&id)
            .ok_or(FlowError::ExecutionNotFound(id))?;

        let mut state = handle.state.write().await;
        match *state {
            ExecutionState::Paused => {
                handle.signal_tx.send(FlowSignal::Run).ok();
                *state = ExecutionState::Running;
                Ok(())
            }
            ref s => Err(FlowError::InvalidTransition {
                action: "resume".into(),
                from: s.as_str().into(),
            }),
        }
    }

    /// Terminate an execution immediately.
    ///
    /// Sends a cancellation signal. The execution task stops at the next
    /// cancellation checkpoint (between waves, or within a wave's result
    /// collection). If the execution is currently paused it is unblocked so
    /// it can observe the cancellation.
    ///
    /// # Errors
    ///
    /// - [`FlowError::ExecutionNotFound`] if the ID is unknown.
    /// - [`FlowError::InvalidTransition`] if the execution is already in a
    ///   terminal state (`Completed`, `Failed`, `Terminated`).
    pub async fn terminate(&self, id: Uuid) -> Result<()> {
        let executions = self.executions.read().await;
        let handle = executions
            .get(&id)
            .ok_or(FlowError::ExecutionNotFound(id))?;

        let state = handle.state.read().await;
        if state.is_terminal() {
            return Err(FlowError::InvalidTransition {
                action: "terminate".into(),
                from: state.as_str().into(),
            });
        }
        drop(state);

        handle.cancel.cancel();
        // Unblock a paused runner so it can observe the cancellation.
        handle.signal_tx.send(FlowSignal::Run).ok();
        Ok(())
    }

    /// Return a snapshot of the current state of an execution.
    ///
    /// # Errors
    ///
    /// - [`FlowError::ExecutionNotFound`] if the ID is unknown.
    pub async fn state(&self, id: Uuid) -> Result<ExecutionState> {
        let executions = self.executions.read().await;
        let handle = executions
            .get(&id)
            .ok_or(FlowError::ExecutionNotFound(id))?;
        // Clone while the guard is still held, then drop the guard before returning.
        let snapshot = handle.state.read().await.clone();
        Ok(snapshot)
    }

    // ── Context CRUD ───────────────────────────────────────────────────────

    /// Return a snapshot of the shared mutable context for a running execution.
    ///
    /// The context is a `HashMap<String, Value>` that nodes may read and write
    /// via [`ExecContext::context`](crate::node::ExecContext::context) during
    /// execution. This method lets the caller inspect (or react to) the
    /// accumulated state from outside the runner.
    ///
    /// # Errors
    ///
    /// - [`FlowError::ExecutionNotFound`] if the ID is unknown.
    pub async fn get_context(&self, id: Uuid) -> Result<HashMap<String, Value>> {
        let executions = self.executions.read().await;
        let handle = executions
            .get(&id)
            .ok_or(FlowError::ExecutionNotFound(id))?;
        let snapshot = handle.context.read().unwrap().clone();
        Ok(snapshot)
    }

    /// Insert or overwrite a single entry in the shared context of a running
    /// execution.
    ///
    /// The change is immediately visible to any node that reads the context
    /// after this call returns.
    ///
    /// # Errors
    ///
    /// - [`FlowError::ExecutionNotFound`] if the ID is unknown.
    pub async fn set_context_entry(&self, id: Uuid, key: String, value: Value) -> Result<()> {
        let executions = self.executions.read().await;
        let handle = executions
            .get(&id)
            .ok_or(FlowError::ExecutionNotFound(id))?;
        handle.context.write().unwrap().insert(key, value);
        Ok(())
    }

    /// Remove a single entry from the shared context of a running execution.
    ///
    /// Returns `true` if the key existed and was removed, `false` if it was
    /// not present.
    ///
    /// # Errors
    ///
    /// - [`FlowError::ExecutionNotFound`] if the ID is unknown.
    pub async fn delete_context_entry(&self, id: Uuid, key: &str) -> Result<bool> {
        let executions = self.executions.read().await;
        let handle = executions
            .get(&id)
            .ok_or(FlowError::ExecutionNotFound(id))?;
        let removed = handle.context.write().unwrap().remove(key).is_some();
        Ok(removed)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::node::{ExecContext, Node};
    use async_trait::async_trait;
    use serde_json::{json, Value};
    use std::time::Duration;

    // ── Helpers ────────────────────────────────────────────────────────────

    /// A node that sleeps for the given duration before returning.
    struct SlowNode(Duration);

    #[async_trait]
    impl Node for SlowNode {
        fn node_type(&self) -> &str {
            "slow"
        }

        async fn execute(&self, _ctx: ExecContext) -> crate::error::Result<Value> {
            tokio::time::sleep(self.0).await;
            Ok(json!({}))
        }
    }

    fn slow_engine(delay: Duration) -> FlowEngine {
        let mut registry = NodeRegistry::with_defaults();
        registry.register(Arc::new(SlowNode(delay)));
        FlowEngine::new(registry)
    }

    fn simple_def() -> Value {
        json!({
            "nodes": [
                { "id": "a", "type": "noop" },
                { "id": "b", "type": "noop" }
            ],
            "edges": [{ "source": "a", "target": "b" }]
        })
    }

    fn slow_def() -> Value {
        json!({
            "nodes": [
                { "id": "a", "type": "slow" },
                { "id": "b", "type": "slow" }
            ],
            "edges": [{ "source": "a", "target": "b" }]
        })
    }

    // ── node_types ─────────────────────────────────────────────────────────

    #[test]
    fn node_types_includes_builtins() {
        let engine = FlowEngine::new(NodeRegistry::with_defaults());
        let types = engine.node_types();
        assert!(types.contains(&"noop".to_string()));
    }

    #[test]
    fn node_types_includes_custom_nodes() {
        let mut registry = NodeRegistry::with_defaults();
        registry.register(Arc::new(SlowNode(Duration::from_millis(1))));
        let engine = FlowEngine::new(registry);

        let types = engine.node_types();
        assert!(types.contains(&"noop".to_string()));
        assert!(types.contains(&"slow".to_string()));
    }

    #[test]
    fn node_types_is_sorted() {
        let engine = FlowEngine::new(NodeRegistry::with_defaults());
        let types = engine.node_types();
        let mut sorted = types.clone();
        sorted.sort();
        assert_eq!(types, sorted);
    }

    #[test]
    fn node_descriptors_include_builtin_metadata() {
        let engine = FlowEngine::new(NodeRegistry::with_defaults());
        let descriptors = engine.node_descriptors();
        let llm = descriptors
            .iter()
            .find(|descriptor| descriptor.node_type == "llm")
            .unwrap();
        assert_eq!(llm.display_name, "LLM");
        assert_eq!(llm.category, "ai");
        assert!(llm.summary.contains("OpenAI-compatible"));
        assert!(llm.default_data.is_object());
        assert!(!llm.fields.is_empty());
    }

    #[test]
    fn node_descriptors_include_custom_nodes() {
        let mut registry = NodeRegistry::with_defaults();
        registry.register(Arc::new(SlowNode(Duration::from_millis(1))));
        let engine = FlowEngine::new(registry);

        let descriptors = engine.node_descriptors();
        let slow = descriptors
            .iter()
            .find(|descriptor| descriptor.node_type == "slow")
            .unwrap();
        assert_eq!(slow.display_name, "slow");
        assert_eq!(slow.category, "custom");
    }

    #[test]
    fn register_node_type_adds_custom_type_at_runtime() {
        let engine = FlowEngine::new(NodeRegistry::with_defaults());
        engine.register_node_type(Arc::new(SlowNode(Duration::from_millis(1))));

        let types = engine.node_types();
        assert!(types.contains(&"slow".to_string()));
    }

    #[test]
    fn register_node_type_with_descriptor_updates_catalog() {
        let engine = FlowEngine::new(NodeRegistry::with_defaults());
        engine.register_node_type_with_descriptor(
            Arc::new(SlowNode(Duration::from_millis(1))),
            NodeDescriptor {
                node_type: "ignored".to_string(),
                display_name: "Slow Node".to_string(),
                category: "testing".to_string(),
                summary: "Sleeps briefly during tests.".to_string(),
                default_data: json!({ "delay_ms": 1 }),
                fields: vec![],
            },
        );

        let slow = engine
            .node_descriptors()
            .into_iter()
            .find(|descriptor| descriptor.node_type == "slow")
            .unwrap();
        assert_eq!(slow.display_name, "Slow Node");
        assert_eq!(slow.category, "testing");
        assert_eq!(slow.default_data["delay_ms"], 1);
    }

    #[test]
    fn unregister_node_type_removes_runtime_type() {
        let engine = FlowEngine::new(NodeRegistry::with_defaults());
        engine.register_node_type(Arc::new(SlowNode(Duration::from_millis(1))));

        assert!(engine.unregister_node_type("slow").unwrap());
        assert!(!engine.node_types().contains(&"slow".to_string()));

        let def = json!({
            "nodes": [{ "id": "a", "type": "slow" }],
            "edges": []
        });
        let issues = engine.validate(&def);
        assert_eq!(issues.len(), 1);
        assert!(issues[0].message.contains("unknown node type"));
    }

    #[test]
    fn unregister_node_type_rejects_builtin_types() {
        let engine = FlowEngine::new(NodeRegistry::with_defaults());

        let err = engine.unregister_node_type("noop").unwrap_err();
        assert!(matches!(err, FlowError::ProtectedNodeType(ref ty) if ty == "noop"));
        assert!(engine.node_types().contains(&"noop".to_string()));
    }

    #[test]
    fn capabilities_include_node_catalog() {
        let engine = FlowEngine::new(NodeRegistry::with_defaults());
        let capabilities = engine.capabilities();
        assert_eq!(capabilities.version, "2026-03-22");
        assert!(capabilities.progressive_disclosure);
        assert!(capabilities
            .nodes
            .iter()
            .any(|node| node.node_type == "llm"));
    }

    #[test]
    fn http_request_descriptor_carries_editor_metadata() {
        let engine = FlowEngine::new(NodeRegistry::with_defaults());
        let descriptors = engine.node_descriptors();
        let http = descriptors
            .iter()
            .find(|descriptor| descriptor.node_type == "http-request")
            .unwrap();
        assert_eq!(http.default_data["method"], "GET");
        assert!(http.fields.iter().any(|field| field.key == "url"));
    }

    // ── start ──────────────────────────────────────────────────────────────

    #[tokio::test]
    async fn start_returns_execution_id() {
        let engine = FlowEngine::new(NodeRegistry::with_defaults());
        let id = engine.start(&simple_def(), HashMap::new()).await.unwrap();
        // ID is non-nil.
        assert!(!id.is_nil());
    }

    #[tokio::test]
    async fn start_rejects_invalid_definition() {
        let engine = FlowEngine::new(NodeRegistry::with_defaults());
        let bad = json!({
            "nodes": [{ "id": "a", "type": "noop" }],
            "edges": [{ "source": "ghost", "target": "a" }]
        });
        assert!(matches!(
            engine.start(&bad, HashMap::new()).await,
            Err(FlowError::UnknownNode(_))
        ));
    }

    #[tokio::test]
    async fn completed_flow_has_outputs() {
