//! Error types for a3s-flow.

use thiserror::Error;
use uuid::Uuid;

/// All errors produced by the flow engine.
#[derive(Debug, Error)]
pub enum FlowError {
    /// The JSON DAG definition is invalid (missing fields, bad structure).
    #[error("invalid flow definition: {0}")]
    InvalidDefinition(String),

    /// The DAG contains a cycle, which is forbidden.
    #[error("flow graph contains a cycle")]
    CyclicGraph,

    /// A referenced node ID does not exist in the flow definition.
    #[error("unknown node id: {0}")]
    UnknownNode(String),

    /// A node execution failed.
    #[error("node '{node_id}' failed during execution '{execution_id}': {reason}")]
    NodeFailed {
        node_id: String,
        execution_id: Uuid,
        reason: String,
    },

    /// The execution was terminated by an external signal.
    #[error("execution was terminated")]
    Terminated,

    /// No execution found for the given ID.
    #[error("execution not found: {0}")]
    ExecutionNotFound(Uuid),

    /// No flow definition found for the given name in the configured [`FlowStore`](crate::flow_store::FlowStore).
    #[error("flow not found: {0}")]
    FlowNotFound(String),

    /// The requested node type is protected and cannot be removed at runtime.
    #[error("node type is protected and cannot be removed: {0}")]
    ProtectedNodeType(String),

    /// The requested state transition is not valid for the current state.
    #[error("cannot {action} a {from} execution")]
    InvalidTransition { action: String, from: String },

    /// JSON serialization / deserialization error.
    #[error("json error: {0}")]
    Json(#[from] serde_json::Error),

    /// An unexpected internal error.
    #[error("internal error: {0}")]
    Internal(String),
}

pub type Result<T> = std::result::Result<T, FlowError>;

//! [`EventEmitter`] — node and flow lifecycle event extension point.
//!
//! Implement [`EventEmitter`] to react to workflow execution events — e.g. to
//! stream progress to a UI, collect metrics, or integrate with `a3s-event`.
//!
//! Register a custom emitter via
//! [`FlowEngine::with_event_emitter`](crate::engine::FlowEngine::with_event_emitter) or
//! [`FlowRunner::with_event_emitter`](crate::runner::FlowRunner::with_event_emitter).
//! The built-in [`NoopEventEmitter`] is used when no custom emitter is set.
//!
//! For pull-based event consumption, use
//! [`FlowEngine::start_streaming`](crate::engine::FlowEngine::start_streaming)
//! which returns a [`tokio::sync::broadcast::Receiver<FlowEvent>`].

use std::sync::Arc;

use async_trait::async_trait;
use serde::{Deserialize, Serialize};
use serde_json::Value;
use tokio::sync::broadcast;
use uuid::Uuid;

use crate::result::FlowResult;

/// Execution metadata attached to a node completion event.
///
/// Carries token usage, pricing, and iteration/loop context for AI nodes.
#[derive(Debug, Clone, Serialize, Deserialize, Default)]
pub struct NodeExecutionMetadata {
    /// Total tokens consumed (prompt + completion).
    pub total_tokens: Option<u64>,
    /// Tokens in the prompt.
    pub prompt_tokens: Option<u64>,
    /// Tokens in the completion.
    pub completion_tokens: Option<u64>,
    /// Estimated total cost.
    pub total_price: Option<f64>,
    /// Currency for the price (e.g. "USD").
    pub currency: Option<String>,
    /// ID of the iteration this node ran inside.
    pub iteration_id: Option<String>,
    /// 0-based index of the iteration.
    pub iteration_index: Option<u32>,
    /// ID of the loop this node ran inside.
    pub loop_id: Option<String>,
    /// 0-based index of the loop iteration.
    pub loop_index: Option<u32>,
    /// ID of the parallel branch group.
    pub parallel_id: Option<String>,
    /// ID of the parent parallel group.
    pub parent_parallel_id: Option<String>,
    /// Node ID where the parallel section started.
    pub parent_parallel_start_node_id: Option<String>,
    /// Error handling strategy.
    pub error_strategy: Option<String>,
    /// Agent reasoning/tool logs.
    #[serde(default)]
    pub agent_log: Vec<AgentLogEntry>,
}

/// A single entry in an agent's reasoning or tool-call log.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct AgentLogEntry {
    /// Unique message ID.
    pub id: String,
    /// Parent message ID for threading.
    pub parent_id: Option<String>,
    /// Human-readable label.
    pub label: String,
    /// Log level.
    pub level: String,
    /// Message content.
    pub content: String,
    /// Timestamp in milliseconds.
    pub timestamp: i64,
}

/// A snapshot of a single lifecycle event emitted during flow execution.
///
/// Produced by [`FlowEngine::start_streaming`](crate::engine::FlowEngine::start_streaming)
/// via a [`tokio::sync::broadcast`] channel. All variants are `Clone` so they
/// can be forwarded to multiple subscribers.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub enum FlowEvent {
    /// A flow execution started.
    FlowStarted { execution_id: Uuid },
    /// A flow execution completed successfully.
    FlowCompleted {
        execution_id: Uuid,
        result: FlowResult,
    },
    /// A flow execution failed (node error or internal error).
    FlowFailed { execution_id: Uuid, reason: String },
    /// A flow execution was terminated externally.
    FlowTerminated { execution_id: Uuid },
    /// A node is about to execute.
    NodeStarted {
        execution_id: Uuid,
        node_id: String,
        node_type: String,
    },
    /// A node completed successfully (legacy — prefer NodeCompletedFull).
    NodeCompleted {
        execution_id: Uuid,
        node_id: String,
        output: Value,
    },
    /// A node completed with full metadata.
    NodeCompletedFull {
        execution_id: Uuid,
        node_id: String,
        node_type: String,
        /// The inputs passed to this node from its dependencies.
        inputs: Value,
        /// Intermediate processing data (e.g. rendered prompt for LLM nodes).
        process_data: Option<Value>,
        /// The node's output value.
        outputs: Value,
        /// Execution time in milliseconds.
        elapsed_time_ms: u64,
        /// Token usage, pricing, iteration context, etc.
        metadata: Option<NodeExecutionMetadata>,
    },
    /// A node was skipped because its `run_if` guard evaluated to false.
    NodeSkipped { execution_id: Uuid, node_id: String },
    /// A node failed (all retry attempts exhausted).
    NodeFailed {
        execution_id: Uuid,
        node_id: String,
        reason: String,
    },
    /// An iteration sub-flow started.
    IterationStarted {
        execution_id: Uuid,
        node_id: String,
        iteration_id: String,
        iteration_index: u32,
    },
    /// An iteration sub-flow produced another result (next item).
    IterationNext {
        execution_id: Uuid,
        node_id: String,
        iteration_id: String,
        iteration_index: u32,
    },
    /// An iteration sub-flow completed.
    IterationCompleted {
        execution_id: Uuid,
        node_id: String,
        iteration_id: String,
    },
    /// A loop sub-flow started.
    LoopStarted {
        execution_id: Uuid,
        node_id: String,
        loop_id: String,
        loop_index: u32,
    },
    /// A loop sub-flow completed.
    LoopCompleted {
        execution_id: Uuid,
        node_id: String,
        loop_id: String,
    },
    /// A parallel branch started executing.
    ParallelBranchStarted {
        execution_id: Uuid,
        node_id: String,
        parallel_id: String,
        branch_id: String,
    },
    /// A parallel branch finished.
    ParallelBranchCompleted {
        execution_id: Uuid,
        node_id: String,
        parallel_id: String,
        branch_id: String,
    },
    /// A node is being retried after a failure.
    NodeRetry {
        execution_id: Uuid,
        node_id: String,
        retry_index: u32,
        max_retries: u32,
    },
}

/// An [`EventEmitter`] that forwards all events into a broadcast channel.
///
/// Created internally by [`FlowEngine::start_streaming`](crate::engine::FlowEngine::start_streaming).
pub(crate) struct ChannelEmitter {
    tx: broadcast::Sender<FlowEvent>,
}

impl ChannelEmitter {
    pub(crate) fn new(tx: broadcast::Sender<FlowEvent>) -> Self {
        Self { tx }
    }
}

#[async_trait]
impl EventEmitter for ChannelEmitter {
    async fn on_flow_started(&self, execution_id: Uuid) {
        let _ = self.tx.send(FlowEvent::FlowStarted { execution_id });
    }

    async fn on_flow_completed(&self, execution_id: Uuid, result: &FlowResult) {
        let _ = self.tx.send(FlowEvent::FlowCompleted {
            execution_id,
            result: result.clone(),
        });
    }

    async fn on_flow_failed(&self, execution_id: Uuid, reason: &str) {
        let _ = self.tx.send(FlowEvent::FlowFailed {
            execution_id,
            reason: reason.to_string(),
        });
    }

    async fn on_flow_terminated(&self, execution_id: Uuid) {
        let _ = self.tx.send(FlowEvent::FlowTerminated { execution_id });
    }

    async fn on_node_started(&self, execution_id: Uuid, node_id: &str, node_type: &str) {
        let _ = self.tx.send(FlowEvent::NodeStarted {
            execution_id,
            node_id: node_id.to_string(),
            node_type: node_type.to_string(),
        });
    }

    async fn on_node_completed(&self, execution_id: Uuid, node_id: &str, output: &Value) {
        let _ = self.tx.send(FlowEvent::NodeCompleted {
            execution_id,
            node_id: node_id.to_string(),
            output: output.clone(),
        });
    }

    async fn on_node_completed_full(
        &self,
        execution_id: Uuid,
        node_id: &str,
        node_type: &str,
        inputs: &Value,
        process_data: Option<&Value>,
        outputs: &Value,
        elapsed_time_ms: u64,
        metadata: Option<&NodeExecutionMetadata>,
    ) {
        let _ = self.tx.send(FlowEvent::NodeCompletedFull {
            execution_id,
            node_id: node_id.to_string(),
            node_type: node_type.to_string(),
            inputs: inputs.clone(),
            process_data: process_data.cloned(),
            outputs: outputs.clone(),
            elapsed_time_ms,
            metadata: metadata.cloned(),
        });
    }

    async fn on_node_skipped(&self, execution_id: Uuid, node_id: &str) {
        let _ = self.tx.send(FlowEvent::NodeSkipped {
            execution_id,
            node_id: node_id.to_string(),
        });
    }

    async fn on_node_failed(&self, execution_id: Uuid, node_id: &str, reason: &str) {
        let _ = self.tx.send(FlowEvent::NodeFailed {
            execution_id,
            node_id: node_id.to_string(),
            reason: reason.to_string(),
        });
    }

    async fn on_iteration_started(
        &self,
        execution_id: Uuid,
        node_id: &str,
        iteration_id: &str,
        iteration_index: u32,
    ) {
        let _ = self.tx.send(FlowEvent::IterationStarted {
            execution_id,
            node_id: node_id.to_string(),
            iteration_id: iteration_id.to_string(),
            iteration_index,
        });
    }

    async fn on_iteration_next(
        &self,
        execution_id: Uuid,
        node_id: &str,
        iteration_id: &str,
        iteration_index: u32,
    ) {
        let _ = self.tx.send(FlowEvent::IterationNext {
            execution_id,
            node_id: node_id.to_string(),
            iteration_id: iteration_id.to_string(),
            iteration_index,
        });
    }

    async fn on_iteration_completed(&self, execution_id: Uuid, node_id: &str, iteration_id: &str) {
        let _ = self.tx.send(FlowEvent::IterationCompleted {
            execution_id,
            node_id: node_id.to_string(),
            iteration_id: iteration_id.to_string(),
        });
    }

    async fn on_loop_started(
        &self,
        execution_id: Uuid,
        node_id: &str,
        loop_id: &str,
        loop_index: u32,
    ) {
        let _ = self.tx.send(FlowEvent::LoopStarted {
            execution_id,
            node_id: node_id.to_string(),
            loop_id: loop_id.to_string(),
            loop_index,
        });
    }

    async fn on_loop_completed(&self, execution_id: Uuid, node_id: &str, loop_id: &str) {
        let _ = self.tx.send(FlowEvent::LoopCompleted {
            execution_id,
            node_id: node_id.to_string(),
            loop_id: loop_id.to_string(),
        });
    }

    async fn on_parallel_branch_started(
        &self,
        execution_id: Uuid,
        node_id: &str,
        parallel_id: &str,
        branch_id: &str,
    ) {
        let _ = self.tx.send(FlowEvent::ParallelBranchStarted {
            execution_id,
            node_id: node_id.to_string(),
            parallel_id: parallel_id.to_string(),
            branch_id: branch_id.to_string(),
        });
    }

    async fn on_parallel_branch_completed(
        &self,
        execution_id: Uuid,
        node_id: &str,
        parallel_id: &str,
        branch_id: &str,
    ) {
        let _ = self.tx.send(FlowEvent::ParallelBranchCompleted {
            execution_id,
            node_id: node_id.to_string(),
            parallel_id: parallel_id.to_string(),
            branch_id: branch_id.to_string(),
        });
    }

    async fn on_node_retry(
        &self,
        execution_id: Uuid,
        node_id: &str,
        retry_index: u32,
        max_retries: u32,
    ) {
        let _ = self.tx.send(FlowEvent::NodeRetry {
            execution_id,
            node_id: node_id.to_string(),
            retry_index,
            max_retries,
        });
    }
}

/// An [`EventEmitter`] that fans events out to two downstream emitters.
///
/// Used internally by [`FlowEngine::start_streaming`](crate::engine::FlowEngine::start_streaming)
/// to compose a [`ChannelEmitter`] with the engine's existing emitter.
pub(crate) struct MulticastEmitter {
    pub(crate) a: Arc<dyn EventEmitter>,
    pub(crate) b: Arc<dyn EventEmitter>,
}

#[async_trait]
impl EventEmitter for MulticastEmitter {
    async fn on_flow_started(&self, execution_id: Uuid) {
        self.a.on_flow_started(execution_id).await;
        self.b.on_flow_started(execution_id).await;
    }

    async fn on_flow_completed(&self, execution_id: Uuid, result: &FlowResult) {
        self.a.on_flow_completed(execution_id, result).await;
        self.b.on_flow_completed(execution_id, result).await;
    }

    async fn on_flow_failed(&self, execution_id: Uuid, reason: &str) {
        self.a.on_flow_failed(execution_id, reason).await;
        self.b.on_flow_failed(execution_id, reason).await;
    }

    async fn on_flow_terminated(&self, execution_id: Uuid) {
        self.a.on_flow_terminated(execution_id).await;
        self.b.on_flow_terminated(execution_id).await;
    }

    async fn on_node_started(&self, execution_id: Uuid, node_id: &str, node_type: &str) {
        self.a
            .on_node_started(execution_id, node_id, node_type)
            .await;
        self.b
            .on_node_started(execution_id, node_id, node_type)
            .await;
    }

    async fn on_node_completed(&self, execution_id: Uuid, node_id: &str, output: &Value) {
