    ) {
        self.a
            .on_node_completed_full(
                execution_id,
                node_id,
                node_type,
                inputs,
                process_data,
                outputs,
                elapsed_time_ms,
                metadata,
            )
            .await;
        self.b
            .on_node_completed_full(
                execution_id,
