    async fn on_iteration_completed(&self, execution_id: Uuid, node_id: &str, iteration_id: &str) {
        self.a
            .on_iteration_completed(execution_id, node_id, iteration_id)
            .await;
        self.b
            .on_iteration_completed(execution_id, node_id, iteration_id)
