        use crate::runner::FlowRunner;
        use serde_json::json;
        use std::collections::HashMap;

        struct FailNode;
        #[async_trait]
        impl Node for FailNode {
            fn node_type(&self) -> &str {
                "fail-always"
            }
            async fn execute(&self, _: ExecContext) -> crate::error::Result<Value> {
                Err(FlowError::Internal("boom".into()))
            }
        }

        let mut registry = NodeRegistry::with_defaults();
        registry.register(Arc::new(FailNode));

        let def = json!({ "nodes": [{ "id": "x", "type": "fail-always" }], "edges": [] });
        let dag = DagGraph::from_json(&def).unwrap();
        let (emitter, counts) = CountEmitter::new();
        let runner =
            FlowRunner::new(dag, registry).with_event_emitter(emitter as Arc<dyn EventEmitter>);

        let _ = runner.run(HashMap::new()).await;

        assert_eq!(counts.nf.load(Ordering::SeqCst), 1, "node_failed");
        assert_eq!(counts.fa.load(Ordering::SeqCst), 1, "flow_failed");
        assert_eq!(counts.c.load(Ordering::SeqCst), 0, "not completed");
    }
}

//! Execution handle and state types.
//!
//! [`ExecutionState`] is the public snapshot of a workflow execution.
//! [`ExecutionHandle`] is an internal struct held by [`FlowEngine`] to control
//! a running execution via a signal channel and a cancellation token.

use std::collections::HashMap;
use std::sync::{Arc, RwLock};

use serde_json::Value;
use tokio::sync::{broadcast, watch, RwLock as AsyncRwLock};
use tokio_util::sync::CancellationToken;

use crate::event::FlowEvent;
use crate::result::FlowResult;
use crate::runner::FlowSignal;

/// Snapshot of a workflow execution's current lifecycle state.
#[derive(Debug, Clone)]
pub enum ExecutionState {
    /// Actively executing nodes.
    Running,
    /// Paused at a wave boundary; waiting for a resume signal.
    Paused,
    /// Finished successfully. Contains the per-node outputs.
    Completed(FlowResult),
    /// Aborted due to a node error. Contains the error message.
    Failed(String),
    /// Stopped by an external [`FlowEngine::terminate`](crate::engine::FlowEngine::terminate) call.
    Terminated,
}

impl ExecutionState {
    /// Short label used in error messages.
    pub fn as_str(&self) -> &'static str {
        match self {
            Self::Running => "running",
            Self::Paused => "paused",
            Self::Completed(_) => "completed",
            Self::Failed(_) => "failed",
            Self::Terminated => "terminated",
        }
    }

    /// Returns `true` if the execution has reached a terminal state and will
    /// not change again.
    pub fn is_terminal(&self) -> bool {
        matches!(
            self,
            Self::Completed(_) | Self::Failed(_) | Self::Terminated
        )
    }
}

/// Internal control handle for a single execution managed by [`FlowEngine`].
pub(crate) struct ExecutionHandle {
    /// Shared, mutable execution state. Updated by the runner task (terminal
    /// states) and by the engine (pause / resume).
    pub(crate) state: Arc<AsyncRwLock<ExecutionState>>,
    /// Sends pause / run signals to the runner task.
    pub(crate) signal_tx: watch::Sender<FlowSignal>,
    /// Cancellation token — call `.cancel()` to terminate the execution.
    pub(crate) cancel: CancellationToken,
    /// Shared mutable context, accessible from both nodes (via ExecContext)
    /// and the engine (via CRUD methods). Uses std::sync::RwLock so nodes
    /// can access it in non-async contexts.
    pub(crate) context: Arc<RwLock<HashMap<String, Value>>>,
    /// Broadcast sender used for live event subscriptions on this execution.
    pub(crate) event_tx: Arc<RwLock<Option<broadcast::Sender<FlowEvent>>>>,
}

//! [`FlowStore`] — flow definition storage extension point.
//!
//! Implement [`FlowStore`] to store and retrieve named JSON flow definitions
//! using any backend (in-memory, SQLite, PostgreSQL, remote API, …).
//!
//! Register a store on [`FlowEngine`](crate::engine::FlowEngine) via
//! [`with_flow_store`](crate::engine::FlowEngine::with_flow_store) to enable
//! [`start_named`](crate::engine::FlowEngine::start_named) — which loads a
//! definition by name and starts it in one step.
//!
//! [`MemoryFlowStore`] is provided as an in-process default.

use std::collections::HashMap;
use std::sync::Arc;

use async_trait::async_trait;
use serde_json::Value;
use tokio::sync::RwLock;

use crate::error::Result;

/// Named storage for JSON flow definitions.
///
/// # Example
///
/// ```rust
/// use a3s_flow::{FlowStore, MemoryFlowStore};
/// use serde_json::json;
/// use std::sync::Arc;
///
/// # #[tokio::main] async fn main() {
/// let store = MemoryFlowStore::new();
///
/// let def = json!({ "nodes": [{ "id": "a", "type": "noop" }], "edges": [] });
/// store.save("my-flow", &def).await.unwrap();
///
/// let loaded = store.load("my-flow").await.unwrap().unwrap();
/// assert_eq!(loaded, def);
/// # }
/// ```
#[async_trait]
pub trait FlowStore: Send + Sync {
    /// Persist a flow definition under the given name (upsert semantics).
    async fn save(&self, name: &str, definition: &Value) -> Result<()>;

    /// Load a flow definition by name.
    ///
    /// Returns `None` if no definition exists with that name.
    async fn load(&self, name: &str) -> Result<Option<Value>>;

    /// List all stored flow names.
    async fn list(&self) -> Result<Vec<String>>;

    /// Delete a stored flow definition. No-op if the name is not found.
    async fn delete(&self, name: &str) -> Result<()>;
}

/// An in-memory [`FlowStore`] backed by a `HashMap` under an `RwLock`.
///
/// Suitable for testing and short-lived processes. Data is lost on restart.
pub struct MemoryFlowStore {
    inner: Arc<RwLock<HashMap<String, Value>>>,
}

impl MemoryFlowStore {
    /// Create a new empty store.
    pub fn new() -> Self {
        Self {
            inner: Arc::new(RwLock::new(HashMap::new())),
        }
    }
}

impl Default for MemoryFlowStore {
    fn default() -> Self {
        Self::new()
    }
}

#[async_trait]
impl FlowStore for MemoryFlowStore {
    async fn save(&self, name: &str, definition: &Value) -> Result<()> {
        self.inner
            .write()
            .await
            .insert(name.to_string(), definition.clone());
        Ok(())
    }

    async fn load(&self, name: &str) -> Result<Option<Value>> {
        Ok(self.inner.read().await.get(name).cloned())
    }

    async fn list(&self) -> Result<Vec<String>> {
        Ok(self.inner.read().await.keys().cloned().collect())
    }

    async fn delete(&self, name: &str) -> Result<()> {
        self.inner.write().await.remove(name);
        Ok(())
    }
}

