//! Node trait and execution context.
//!
//! Every workflow step implements [`Node`]. The engine calls [`Node::execute`]
//! with an [`ExecContext`] containing the node's configuration, upstream outputs,
//! global variables, and a reference to the active [`NodeRegistry`] — which
//! lets nodes like `"iteration"` spin up sub-flow runners without holding their
//! own registry reference.

use std::collections::HashMap;
use std::sync::{Arc, RwLock};

use async_trait::async_trait;
use serde::Deserialize;
use serde_json::Value;

use crate::error::Result;
use crate::flow_store::FlowStore;
use crate::registry::NodeRegistry;

/// Per-node retry configuration, parsed from `data["retry"]`.
///
/// When present, the runner will re-attempt a failed node up to `max_attempts`
/// times (including the first attempt) with an optional exponential backoff.
///
/// # Example (in flow definition)
/// ```json
/// {
///   "id": "fetch",
///   "type": "http-request",
///   "data": {
///     "url": "https://api.example.com/items",
///     "retry": { "max_attempts": 3, "backoff_ms": 500 }
///   }
/// }
/// ```
#[derive(Debug, Clone, Deserialize)]
pub struct RetryPolicy {
    /// Maximum number of attempts (including the first). Minimum effective value: 1.
    pub max_attempts: u32,
    /// Base delay in milliseconds between attempts. Each subsequent retry waits
    /// `backoff_ms * 2^(attempt-1)` milliseconds (capped at 64× the base).
    /// Defaults to 0 (no delay).
    #[serde(default)]
    pub backoff_ms: u64,
}

/// Runtime context passed to every node during execution.
///
/// - `data` — the static configuration declared in the flow definition's `data` field.
/// - `inputs` — outputs of all upstream nodes, keyed by node ID.
/// - `variables` — global flow-level variables (env, secrets, user inputs).
/// - `context` — shared mutable context for cross-node state (similar to Dify's global context).
///   Nodes can read and write to this context using `context.read()` and `context.write()`.
/// - `registry` — the active node registry; available to nodes that need to
///   execute sub-flows (e.g. `"iteration"`, `"sub-flow"`).
/// - `flow_store` — optional named flow definition store; required by the
///   `"sub-flow"` node to load its target definition by name.
pub struct ExecContext {
    /// Node configuration from the flow definition's `data` field.
    pub data: Value,
    /// Outputs of upstream nodes, keyed by node ID.
    pub inputs: HashMap<String, Value>,
    /// Global flow variables (env, secrets, user inputs).
    pub variables: HashMap<String, Value>,
    /// Shared mutable context for cross-node state (Dify-style global context).
    /// Use `context.read()` to read and `context.write()` to modify.
    pub context: Arc<RwLock<HashMap<String, Value>>>,
    /// Active node registry — allows nodes to run sub-flows.
    pub registry: Arc<NodeRegistry>,
    /// Named flow definition store — available when the engine has one configured.
    pub flow_store: Option<Arc<dyn FlowStore>>,
}

impl Clone for ExecContext {
    fn clone(&self) -> Self {
        Self {
            data: self.data.clone(),
            inputs: self.inputs.clone(),
            variables: self.variables.clone(),
            context: Arc::clone(&self.context),
            registry: Arc::clone(&self.registry),
            flow_store: self.flow_store.clone(),
        }
    }
}

impl std::fmt::Debug for ExecContext {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("ExecContext")
            .field("data", &self.data)
            .field("inputs", &self.inputs)
            .field("variables", &self.variables)
            .field("context", &"<RwLock>")
            .finish_non_exhaustive()
    }
}

impl Default for ExecContext {
    fn default() -> Self {
        Self {
            data: Value::Null,
            inputs: HashMap::new(),
            variables: HashMap::new(),
            context: Arc::new(RwLock::new(HashMap::new())),
            registry: Arc::new(NodeRegistry::with_defaults()),
            flow_store: None,
        }
    }
}

/// The extension point for workflow nodes.
///
/// Implement this trait to add custom node types (HTTP call, LLM prompt,
/// script, condition branch, sub-flow, etc.). Every implementation must be
/// `Send + Sync` so the runner can execute nodes concurrently across threads.
#[async_trait]
pub trait Node: Send + Sync {
    /// The node type identifier matched against the `"type"` field in the
    /// flow definition and looked up in [`NodeRegistry`].
    fn node_type(&self) -> &str;

    /// Execute the node and return a JSON output value.
    ///
    /// The output is stored under this node's ID and passed as `inputs` to
    /// all downstream nodes.
    async fn execute(&self, ctx: ExecContext) -> Result<Value>;
}

//! `"agent"` node — multi-turn LLM agent with tool calling.
//!
//! Maintains conversation history across turns via `ExecContext.context`,
//! supports OpenAI function-calling style tools, and loops until a stop
//! condition or `max_turns` is reached.

pub mod node;

pub use node::AgentNode;

//! `"agent"` node implementation.

use async_trait::async_trait;
use reqwest::Client;
use serde_json::{json, Value};

use crate::error::{FlowError, Result};
use crate::node::{ExecContext, Node};
use crate::nodes::llm::{build_jinja_context, render, ChatMessage, CompletionResult};

const DEFAULT_API_BASE: &str = "https://api.openai.com/v1";
const DEFAULT_TEMPERATURE: f64 = 0.7;
const DEFAULT_MAX_TURNS: usize = 10;
const CONVERSATION_KEY: &str = "conversation";

/// Agent node — multi-turn LLM with function calling.
pub struct AgentNode;

#[async_trait]
impl Node for AgentNode {
    fn node_type(&self) -> &str {
        "agent"
    }

    async fn execute(&self, ctx: ExecContext) -> Result<Value> {
        let config = AgentConfig::from_data(&ctx.data)?;
        let jinja_ctx = build_jinja_context(&ctx);

        // 1. Load existing conversation from context
        let conversation = load_conversation(&ctx)?;
        let mut messages: Vec<ChatMessage> = conversation;

        // 2. Inject system prompt if not already in conversation
        if let Some(ref sys) = config.system_prompt {
            if messages.iter().all(|m| m.role != "system") {
                let sys_content = render(sys, &jinja_ctx)?;
                messages.insert(
                    0,
                    ChatMessage {
                        role: "system".into(),
                        content: sys_content,
                    },
                );
            }
        }

        // 3. Render and append user message
        let user_content = render(&config.user_message_template, &jinja_ctx)?;
        messages.push(ChatMessage {
            role: "user".into(),
            content: user_content,
        });

        // 3. Main agent loop
        let mut tool_call_log: Vec<ToolCallEntry> = Vec::new();
        let mut final_text = String::new();
        let mut turns = 0;

        loop {
            turns += 1;
            if turns > config.max_turns {
                final_text = format!(
                    "[Agent reached max_turns ({}) without completing]",
                    config.max_turns
                );
                break;
            }

            // Call LLM (with tools if configured)
            let result = do_agent_completion(
                &config.api_base,
                &config.api_key,
                &config.model,
                messages.clone(),
                Some(config.temperature),
                config.max_tokens,
                &config.tools,
            )
            .await?;

            // Check finish reason
            if result.finish_reason == "tool_calls" {
                // Parse tool calls from response
                let tool_calls = parse_tool_calls(&result.text)?;
                for tc in tool_calls {
                    let tool_result = execute_tool(&tc.name, &tc.arguments).await;
                    let result_content = match &tool_result {
                        Ok(output) => output.clone(),
                        Err(e) => format!("error: {}", e),
                    };
                    tool_call_log.push(ToolCallEntry {
                        tool: tc.name.clone(),
                        args: tc.arguments,
                        result: result_content.clone(),
                    });
                    // Append tool result as assistant message with tool call id
                    messages.push(ChatMessage {
                        role: "assistant".into(),
                        content: result.text.clone(),
                    });
                    messages.push(ChatMessage {
                        role: "tool".into(),
                        content: result_content,
                    });
                }
                // Continue loop with updated messages
                continue;
            } else {
                // Stop — final response
                final_text = result.text;
                messages.push(ChatMessage {
                    role: "assistant".into(),
                    content: final_text.clone(),
                });
                break;
            }
        }

        // 4. Persist conversation back to context
        save_conversation(&ctx, &messages)?;

        Ok(json!({
            "text": final_text,
            "conversation": messages,
            "tool_calls": tool_call_log,
            "turns": turns,
        }))
    }
}

// ── Config ────────────────────────────────────────────────────────────────────

#[derive(Debug)]
struct AgentConfig {
    model: String,
    system_prompt: Option<String>,
    user_message_template: String,
    api_base: String,
    api_key: String,
    temperature: f64,
    max_tokens: Option<u64>,
    tools: Vec<Value>,
    max_turns: usize,
}

impl AgentConfig {
    fn from_data(data: &Value) -> Result<Self> {
        let model = data["model"]
            .as_str()
            .ok_or_else(|| FlowError::InvalidDefinition("agent: missing data.model".into()))?
            .to_string();

        let user_message_template = data["user_message_template"]
            .as_str()
            .ok_or_else(|| {
                FlowError::InvalidDefinition("agent: missing data.user_message_template".into())
            })?
            .to_string();

        let system_prompt = data["system_prompt"].as_str().map(str::to_string);
        let api_base = data["api_base"]
            .as_str()
            .unwrap_or(DEFAULT_API_BASE)
            .trim_end_matches('/')
            .to_string();
        let api_key = data["api_key"].as_str().unwrap_or("").to_string();
        let temperature = data["temperature"].as_f64().unwrap_or(DEFAULT_TEMPERATURE);
        let max_tokens = data["max_tokens"].as_u64();
        let max_turns = data["max_turns"]
            .as_u64()
            .unwrap_or(DEFAULT_MAX_TURNS as u64) as usize;
        let tools = data["tools"].as_array().cloned().unwrap_or_default();

        Ok(Self {
            model,
            system_prompt,
            user_message_template,
            api_base,
            api_key,
            temperature,
            max_tokens,
            tools,
            max_turns,
        })
    }
}

// ── Conversation persistence ──────────────────────────────────────────────────

fn load_conversation(ctx: &ExecContext) -> Result<Vec<ChatMessage>> {
    let guard = ctx
        .context
        .read()
        .map_err(|_| FlowError::Internal("agent: failed to lock context".into()))?;
    if let Some(conv) = guard.get(CONVERSATION_KEY) {
        serde_json::from_value(conv.clone())
            .map_err(|e| FlowError::Internal(format!("agent: invalid conversation format: {}", e)))
    } else {
        Ok(Vec::new())
    }
}

fn save_conversation(ctx: &ExecContext, messages: &[ChatMessage]) -> Result<()> {
    let conv_value = serde_json::to_value(messages).map_err(|e| {
        FlowError::Internal(format!("agent: failed to serialize conversation: {}", e))
    })?;
    let mut guard = ctx
        .context
        .write()
        .map_err(|_| FlowError::Internal("agent: failed to lock context for write".into()))?;
    guard.insert(CONVERSATION_KEY.into(), conv_value);
    Ok(())
}

// ── LLM call with tools ─────────────────────────────────────────────────────

async fn do_agent_completion(
    api_base: &str,
    api_key: &str,
    model: &str,
    messages: Vec<ChatMessage>,
    temperature: Option<f64>,
    max_tokens: Option<u64>,
    tools: &[Value],
) -> Result<CompletionResult> {
    // Inject system prompt as first message if present
    // (already handled by caller, but we handle it here for re-entrant calls)

    let mut body = json!({
        "model": model,
        "messages": messages,
        "temperature": temperature.unwrap_or(DEFAULT_TEMPERATURE),
    });
    if let Some(max_tok) = max_tokens {
        body["max_tokens"] = json!(max_tok);
    }
    if !tools.is_empty() {
        body["tools"] = json!(tools);
    }

    let url = format!("{}/chat/completions", api_base);
    let client = Client::new();
    let mut req = client.post(&url).json(&body);
    if !api_key.is_empty() {
        req = req.bearer_auth(api_key);
    }

    let response = req
        .send()
        .await
        .map_err(|e| FlowError::Internal(format!("agent: HTTP request failed: {}", e)))?;

    let status = response.status();
    let text = response
        .text()
        .await
        .map_err(|e| FlowError::Internal(format!("agent: failed to read response body: {}", e)))?;

    if !status.is_success() {
        return Err(FlowError::Internal(format!(
            "agent: API returned {}: {}",
            status, text
        )));
    }

    let resp: Value = serde_json::from_str(&text)
        .map_err(|e| FlowError::Internal(format!("agent: failed to parse response JSON: {}", e)))?;

    parse_agent_response(&resp)
}

fn parse_agent_response(resp: &Value) -> Result<CompletionResult> {
    // Try tool_calls format first
    if let Some(tools) = resp
        .get("choices")
        .and_then(|c| c.as_array())
        .and_then(|arr| arr.first())
    {
        if let Some(finish_reason) = tools.get("finish_reason").and_then(|f| f.as_str()) {
            if finish_reason == "tool_calls" {
                // Return the full assistant message for tool call parsing
                let message = tools.get("message").and_then(|m| m.as_str()).unwrap_or("");
                return Ok(CompletionResult {
                    text: message.to_string(),
                    model: resp["model"].as_str().unwrap_or("unknown").to_string(),
                    finish_reason: "tool_calls".to_string(),
                    prompt_tokens: resp
                        .pointer("/usage/prompt_tokens")
                        .and_then(|v| v.as_u64())
                        .unwrap_or(0),
                    completion_tokens: resp
                        .pointer("/usage/completion_tokens")
                        .and_then(|v| v.as_u64())
                        .unwrap_or(0),
                    total_tokens: resp
                        .pointer("/usage/total_tokens")
                        .and_then(|v| v.as_u64())
                        .unwrap_or(0),
                    reasoning: None,
                });
            }
        }
    }

    // Standard completion parse
    let text = resp
        .pointer("/choices/0/message/content")
        .and_then(|v| v.as_str())
        .ok_or_else(|| {
            FlowError::Internal(
                "agent: unexpected response shape (missing choices[0].message.content)".into(),
            )
        })?
        .to_string();

    let finish_reason = resp
        .pointer("/choices/0/finish_reason")
        .and_then(|v| v.as_str())
        .unwrap_or("stop")
        .to_string();

    Ok(CompletionResult {
        text,
        model: resp["model"].as_str().unwrap_or("unknown").to_string(),
        finish_reason,
        prompt_tokens: resp
            .pointer("/usage/prompt_tokens")
            .and_then(|v| v.as_u64())
            .unwrap_or(0),
        completion_tokens: resp
            .pointer("/usage/completion_tokens")
            .and_then(|v| v.as_u64())
            .unwrap_or(0),
        total_tokens: resp
            .pointer("/usage/total_tokens")
            .and_then(|v| v.as_u64())
            .unwrap_or(0),
        reasoning: None,
    })
}

// ── Tool call parsing ────────────────────────────────────────────────────────

#[derive(Debug)]
struct ToolCall {
    name: String,
    arguments: Value,
}

fn parse_tool_calls(text: &str) -> Result<Vec<ToolCall>> {
    let data: Value = serde_json::from_str(text).map_err(|e| {
        FlowError::Internal(format!("agent: failed to parse tool call message: {}", e))
    })?;

    let calls = data
        .get("tool_calls")
        .and_then(|tc| tc.as_array())
        .ok_or_else(|| FlowError::Internal("agent: no tool_calls in message".into()))?
        .clone();

    let mut result = Vec::new();
    for call in calls {
        let name = call
            .get("function")
            .and_then(|f| f.get("name"))
            .and_then(|n| n.as_str())
            .ok_or_else(|| FlowError::Internal("agent: malformed tool_call name".into()))?
            .to_string();
        let arguments = call
            .get("function")
            .and_then(|f| f.get("arguments"))
            .cloned()
            .unwrap_or(json!({}));
        result.push(ToolCall { name, arguments });
    }
    Ok(result)
}

// ── Tool execution ───────────────────────────────────────────────────────────

#[derive(Debug, serde::Serialize)]
struct ToolCallEntry {
    tool: String,
    args: Value,
    result: String,
}

async fn execute_tool(tool_name: &str, arguments: &Value) -> Result<String> {
    match tool_name {
        "http_fetch" => execute_http_fetch(arguments).await,
        _ => Err(FlowError::InvalidDefinition(format!(
            "agent: unknown tool '{}'",
            tool_name
        ))),
    }
}

async fn execute_http_fetch(args: &Value) -> Result<String> {
    let url = args["url"]
        .as_str()
        .ok_or_else(|| FlowError::InvalidDefinition("http_fetch: missing url".into()))?;
    let method = args["method"].as_str().unwrap_or("GET");
    let headers = args["headers"].as_object().cloned().unwrap_or_default();
    let body = args.get("body").cloned();

    let client = Client::new();
    let mut req = match method.to_ascii_uppercase().as_str() {
        "GET" => client.get(url),
        "POST" => client.post(url),
        "PUT" => client.put(url),
        "DELETE" => client.delete(url),
        "PATCH" => client.patch(url),
        other => {
            return Err(FlowError::InvalidDefinition(format!(
                "http_fetch: unsupported method '{}'",
                other
            )));
        }
    };

    for (name, val) in headers {
        if let Some(v) = val.as_str() {
            req = req.header(name.as_str(), v);
        }
    }

    if let Some(b) = body {
        if !b.is_null() {
            req = req.json(&b);
        }
    }

    let response = req
        .send()
        .await
        .map_err(|e| FlowError::Internal(format!("http_fetch: request failed: {}", e)))?;

    let status = response.status().as_u16();
    let body_text = response
        .text()
        .await
        .map_err(|e| FlowError::Internal(format!("http_fetch: failed to read response: {}", e)))?;

    let body_json: Value = serde_json::from_str(&body_text).unwrap_or(Value::String(body_text));

    serde_json::to_string(&json!({
        "status": status,
        "body": body_json,
    }))
    .map_err(|e| FlowError::Internal(format!("http_fetch: failed to serialize result: {}", e)))
}

