    }
}

//! Built-in `"http-request"` node — executes an HTTP request and returns the
//! response status, body, and headers.
//!
//! Mirrors Dify's HTTP Request node.
//!
//! # Config schema
//!
//! ```json
//! {
//!   "url":     "https://api.example.com/items",
//!   "method":  "POST",
//!   "headers": { "Authorization": "Bearer {{token}}" },
//!   "body":    { "key": "value" }
//! }
//! ```
//!
//! | Field | Type | Required | Description |
//! |-------|------|:--------:|-------------|
//! | `url` | string | ✓ | Request URL |
//! | `method` | string | | HTTP method — `GET` (default), `POST`, `PUT`, `DELETE`, `PATCH` |
//! | `headers` | object | | String-valued request headers |
//! | `body` | any JSON | | Request body (sent as `application/json`) |
//!
//! # Output schema
//!
//! ```json
//! { "status": 200, "ok": true, "body": { ... } }
//! ```
//!
//! `body` is parsed as JSON when the Content-Type is JSON; otherwise stored
//! as a plain string.

use async_trait::async_trait;
use serde_json::{json, Value};

use crate::error::{FlowError, Result};
use crate::node::{ExecContext, Node};

/// HTTP request node (Dify-compatible).
///
/// Supports `GET`, `POST`, `PUT`, `DELETE`, and `PATCH`.
pub struct HttpRequestNode;

#[async_trait]
impl Node for HttpRequestNode {
    fn node_type(&self) -> &str {
        "http-request"
    }

    async fn execute(&self, ctx: ExecContext) -> Result<Value> {
        let data = &ctx.data;

        let url = data["url"]
            .as_str()
            .ok_or_else(|| FlowError::InvalidDefinition("http-request: missing data.url".into()))?;

        let method = data["method"].as_str().unwrap_or("GET");

        // Build client with timeout and SSL settings
        let mut client_builder = reqwest::Client::builder();

        // Timeout configuration (Dify-style: timeout.connect, timeout.read)
        if let Some(timeout_obj) = data.get("timeout").and_then(|v| v.as_object()) {
            // Support both Dify-style (connect/read) and a3s-style (max_connect_timeout/max_read_timeout)
            let connect_timeout = timeout_obj
                .get("connect")
                .or_else(|| timeout_obj.get("max_connect_timeout"))
                .and_then(|v| v.as_u64())
                .unwrap_or(0);
            let read_timeout = timeout_obj
                .get("read")
                .or_else(|| timeout_obj.get("max_read_timeout"))
                .and_then(|v| v.as_u64())
                .unwrap_or(0);

            if connect_timeout > 0 || read_timeout > 0 {
                let total_timeout = connect_timeout.saturating_add(read_timeout);
                client_builder =
                    client_builder.timeout(std::time::Duration::from_secs(total_timeout));
            }
        }

        // SSL verification (default true)
        let ssl_verify = data
            .get("ssl_verify")
            .and_then(|v| v.as_bool())
            .unwrap_or(true);
        if !ssl_verify {
            client_builder = client_builder.danger_accept_invalid_certs(true);
        }

        let client = client_builder.build().map_err(|e| {
            FlowError::Internal(format!("http-request: failed to build client: {e}"))
        })?;

        let mut req = match method.to_ascii_uppercase().as_str() {
            "GET" => client.get(url),
            "POST" => client.post(url),
            "PUT" => client.put(url),
            "DELETE" => client.delete(url),
            "PATCH" => client.patch(url),
            "HEAD" => client.head(url),
            other => {
                return Err(FlowError::InvalidDefinition(format!(
                    "http-request: unsupported method '{other}'"
                )))
            }
        };

        // Authorization header (Dify-style: authorization.type, authorization.config)
        if let Some(auth_obj) = data.get("authorization").and_then(|v| v.as_object()) {
            let auth_type = auth_obj
                .get("type")
                .and_then(|v| v.as_str())
                .unwrap_or("no-auth");
            if auth_type != "no-auth" {
                if let Some(config) = auth_obj.get("config").and_then(|v| v.as_object()) {
                    let api_key = config.get("api_key").and_then(|v| v.as_str()).unwrap_or("");
                    let header_name = config
                        .get("header")
                        .and_then(|v| v.as_str())
                        .unwrap_or("Authorization");

                    let api_type = config
                        .get("type")
                        .and_then(|v| v.as_str())
                        .unwrap_or("bearer");
                    let header_value = match api_type {
                        "basic" => format!("Basic {}", api_key),
                        "bearer" => format!("Bearer {}", api_key),
                        "custom" => api_key.to_string(),
                        _ => format!("Bearer {}", api_key),
                    };
                    req = req.header(header_name, header_value);
                }
            }
        }

        // Headers (string key-value object or raw string)
        if let Some(headers) = data["headers"].as_object() {
            for (name, val) in headers {
                if let Some(v) = val.as_str() {
                    req = req.header(name.as_str(), v);
                }
            }
        } else if let Some(headers_str) = data["headers"].as_str() {
            // Parse "Key: Value\nKey2: Value2" format
            for line in headers_str.lines() {
                if let Some(pos) = line.find(':') {
                    let key = line[..pos].trim();
                    let value = line[pos + 1..].trim();
                    req = req.header(key, value);
                }
            }
        }

        // Body (Dify-style: body.type, body.data)
        if let Some(body_obj) = data.get("body").and_then(|v| v.as_object()) {
            let body_type = body_obj
                .get("type")
                .and_then(|v| v.as_str())
                .unwrap_or("none");

            if body_type != "none" {
                let body_data = body_obj.get("data");

                match body_type {
                    "json" => {
                        if let Some(data) = body_data {
                            req = req.json(data);
                        }
                    }
                    "x-www-form-urlencoded" => {
                        if let Some(arr) = body_data.and_then(|v| v.as_array()) {
                            let pairs: Vec<(String, String)> = arr
                                .iter()
                                .filter_map(|item| {
                                    let key = item.get("key")?.as_str()?.to_string();
                                    let value = item
                                        .get("value")
                                        .and_then(|v| v.as_str())
                                        .map(String::from)
                                        .or_else(|| {
                                            item.get("value_selector")
                                                .and_then(|v| v.as_str())
                                                .map(String::from)
                                        });
                                    value.map(|v| (key, v))
                                })
                                .collect();
                            // Build x-www-form-urlencoded manually
                            let encoded: String = pairs
                                .iter()
                                .map(|(k, v)| {
                                    format!("{}={}", urlencoding::encode(k), urlencoding::encode(v))
                                })
                                .collect::<Vec<_>>()
                                .join("&");
                            req = req
                                .header("Content-Type", "application/x-www-form-urlencoded")
                                .body(encoded);
                        }
                    }
                    "raw-text" => {
                        if let Some(text) = body_data.and_then(|v| v.as_str()) {
                            req = req
                                .header("Content-Type", "text/plain")
                                .body(text.to_string());
                        }
                    }
                    "binary" => {
                        // Binary body expects a file variable selector
                        if let Some(selector) = body_data.and_then(|v| v.as_str()) {
                            let file_path = resolve_selector_to_string(&ctx.variables, selector)?;
                            let file_bytes = tokio::fs::read(&file_path).await.map_err(|e| {
                                FlowError::Internal(format!(
                                    "http-request: failed to read file '{}': {}",
                                    file_path, e
                                ))
                            })?;
                            req = req
                                .header("Content-Type", "application/octet-stream")
                                .body(file_bytes);
                        }
                    }
                    _ => {}
                }
            }
        } else if let Some(body) = data.get("body") {
            // Legacy: direct body value
            if !body.is_null() {
                req = req.json(body);
            }
        }

        // Retry configuration (Dify-style)
        let retry_config = data.get("retry_config").and_then(|v| v.as_object());
        let max_retries = retry_config
            .and_then(|r| r.get("max_retries"))
            .and_then(|v| v.as_u64())
            .unwrap_or(0) as usize;
        let retry_interval = retry_config
            .and_then(|r| r.get("retry_interval"))
            .and_then(|v| v.as_u64())
            .unwrap_or(100);

        let mut last_error = None;
        for attempt in 0..=max_retries {
            if attempt > 0 {
                tokio::time::sleep(std::time::Duration::from_millis(retry_interval)).await;
            }

            match req.try_clone() {
                Some(req_clone) => match req_clone.send().await {
                    Ok(response) => {
                        let status = response.status().as_u16();
                        let ok = response.status().is_success();

                        let text = response.text().await.map_err(|e| {
                            FlowError::Internal(format!(
                                "http-request: failed to read response: {e}"
                            ))
                        })?;

                        let body: Value =
                            serde_json::from_str(&text).unwrap_or(Value::String(text));

                        return Ok(json!({ "status": status, "ok": ok, "body": body }));
                    }
                    Err(e) => {
                        last_error = Some(e);
                    }
                },
                None => {
                    // Can't retry if request body can't be cloned (e.g., streaming body)
                    let response = req.send().await.map_err(|e| {
                        FlowError::Internal(format!("http-request: request failed: {e}"))
                    })?;
                    let status = response.status().as_u16();
                    let ok = response.status().is_success();

                    let text = response.text().await.map_err(|e| {
                        FlowError::Internal(format!("http-request: failed to read response: {e}"))
                    })?;

                    let body: Value = serde_json::from_str(&text).unwrap_or(Value::String(text));

                    return Ok(json!({ "status": status, "ok": ok, "body": body }));
                }
            }
        }

        Err(FlowError::Internal(format!(
            "http-request: request failed after {} retries: {}",
            max_retries,
            last_error.unwrap()
        )))
    }
}

/// Resolve a selector string like "node_id.field" to a string value from variables.
fn resolve_selector_to_string(
    variables: &std::collections::HashMap<String, Value>,
    selector: &str,
) -> Result<String> {
    let parts: Vec<&str> = selector.split('.').collect();
    if parts.is_empty() {
        return Err(FlowError::InvalidDefinition(
            "http-request: empty selector".into(),
        ));
    }

    let mut current: &Value = variables.get(parts[0]).ok_or_else(|| {
        FlowError::Internal(format!("http-request: variable '{}' not found", parts[0]))
    })?;

    for part in &parts[1..] {
        current = current.get(*part).ok_or_else(|| {
            FlowError::Internal(format!(
                "http-request: path '{}' not found in variable",
                part
            ))
        })?;
    }

    current.as_str().map(String::from).ok_or_else(|| {
        FlowError::InvalidDefinition(format!(
            "http-request: value at '{}' is not a string",
            selector
        ))
    })
}

