            .unwrap();
        let arr = out["output"].as_array().unwrap();
        assert_eq!(arr.len(), 3);
    }

    // ── limit ──────────────────────────────────────────────────────────────

    #[tokio::test]
    async fn limit_truncates_to_n() {
        let node = ListOperatorNode;
        let out = node
            .execute(ctx_with(
                json!({ "input_selector": "src", "limit": 2 }),
                "src",
                json!([10, 20, 30, 40]),
            ))
            .await
            .unwrap();
        assert_eq!(out["output"], json!([10, 20]));
    }

    #[tokio::test]
    async fn limit_larger_than_array_keeps_all() {
        let node = ListOperatorNode;
        let out = node
            .execute(ctx_with(
                json!({ "input_selector": "src", "limit": 100 }),
                "src",
                json!([1, 2]),
            ))
            .await
            .unwrap();
        assert_eq!(out["output"], json!([1, 2]));
    }

    // ── combined pipeline ──────────────────────────────────────────────────

    #[tokio::test]
    async fn filter_sort_limit_combined() {
        let node = ListOperatorNode;
        let out = node
            .execute(ctx_with(
                json!({
                    "input_selector": "src",
                    "filter": { "path": "active", "op": "eq", "value": true },
                    "sort_by": "score",
                    "sort_order": "desc",
                    "limit": 2
                }),
                "src",
                json!([
                    { "name": "A", "score": 5,  "active": true  },
                    { "name": "B", "score": 10, "active": false },
                    { "name": "C", "score": 8,  "active": true  },
                    { "name": "D", "score": 3,  "active": true  },
                    { "name": "E", "score": 12, "active": true  }
                ]),
            ))
            .await
            .unwrap();
        let arr = out["output"].as_array().unwrap();
        // Active: A(5), C(8), D(3), E(12). Sorted desc: E(12), C(8), A(5), D(3). Limit 2: E, C.
        assert_eq!(arr.len(), 2);
        assert_eq!(arr[0]["name"], json!("E"));
        assert_eq!(arr[1]["name"], json!("C"));
    }
}

//! `"llm"` node — OpenAI-compatible chat completion.
//!
//! Renders system and user prompts as Jinja2 templates, calls a
//! `/v1/chat/completions` endpoint, and returns the assistant's reply along
//! with token-usage statistics.
//!
//! Works with any OpenAI-compatible API: OpenAI, Anthropic (via proxy),
//! Ollama, LM Studio, vLLM, Together AI, etc.
//!
//! # Config schema
//!
//! ```json
//! {
//!   "model":         "gpt-4o-mini",
//!   "user_prompt":   "Answer concisely: {{ query }}",
//!   "system_prompt": "You are a helpful assistant.",
//!   "api_base":      "https://api.openai.com/v1",
//!   "api_key":       "sk-...",
//!   "temperature":   0.7,
//!   "max_tokens":    1024
//! }
//! ```
//!
//! | Field | Type | Required | Default | Description |
//! |-------|------|:--------:|---------|-------------|
//! | `model` | string | ✅ | — | Model identifier |
//! | `user_prompt` | string | ✅ | — | User turn — rendered as Jinja2 template |
//! | `system_prompt` | string | — | _(none)_ | System turn — rendered as Jinja2 template |
//! | `api_base` | string | — | `https://api.openai.com/v1` | Base URL (no trailing slash) |
//! | `api_key` | string | — | `""` | Bearer token; may be empty for local models |
//! | `temperature` | number | — | `0.7` | Sampling temperature `[0, 2]` |
//! | `max_tokens` | integer | — | _(none)_ | Max completion tokens |
//!
//! ## Template context
//!
//! Both prompts are Jinja2 templates. The rendering context contains:
//! - All global flow `variables` (by key)
//! - All upstream node outputs (by node ID)
//!
//! Upstream inputs shadow variables with the same key.
//!
//! # Output schema
//!
//! ```json
//! {
//!   "text":          "The answer is 42.",
//!   "model":         "gpt-4o-mini",
//!   "finish_reason": "stop",
//!   "usage": {
//!     "prompt_tokens":     15,
//!     "completion_tokens":  8,
//!     "total_tokens":      23
//!   }
//! }
//! ```

use std::collections::HashMap;

use async_trait::async_trait;
use serde::{Deserialize, Serialize};
use serde_json::{json, Value};

use crate::error::{FlowError, Result};
use crate::node::{ExecContext, Node};

const DEFAULT_API_BASE: &str = "https://api.openai.com/v1";
const DEFAULT_TEMPERATURE: f64 = 0.7;

// ── Public node ───────────────────────────────────────────────────────────────

/// LLM chat-completion node (OpenAI-compatible).
pub struct LlmNode;

#[async_trait]
impl Node for LlmNode {
    fn node_type(&self) -> &str {
        "llm"
    }

    async fn execute(&self, ctx: ExecContext) -> Result<Value> {
        let config = LlmConfig::from_data(&ctx.data)?;
        let jinja_ctx = build_jinja_context(&ctx);

        // Build messages from Dify-style prompt_template if present
        let messages = build_messages(&config, &jinja_ctx)?;

        let result = do_chat_completion_with_options(
            &config.api_base,
            &config.api_key,
            &config.model,
            messages,
            Some(config.temperature),
            config.max_tokens,
            config.structured_output.as_ref(),
            config.reasoning_format.as_deref(),
        )
        .await?;

        let mut output = json!({
            "text": result.text,
            "model": result.model,
            "finish_reason": result.finish_reason,
            "usage": {
                "prompt_tokens":     result.prompt_tokens,
                "completion_tokens": result.completion_tokens,
                "total_tokens":      result.total_tokens,
            }
        });

        // Include reasoning if present (for models that support it)
        if let Some(reasoning) = result.reasoning {
            output["reasoning"] = json!(reasoning);
        }

        Ok(output)
    }
}

// ── Shared internals (used by question-classifier too) ────────────────────────

/// Parsed node configuration.
#[derive(Debug)]
pub(crate) struct LlmConfig {
    pub model: String,
    pub user_prompt: String,
    pub system_prompt: Option<String>,
    pub api_base: String,
    pub api_key: String,
    pub temperature: f64,
    pub max_tokens: Option<u64>,
    /// Dify-style prompt_template: array of prompt items with role, text, edition_type
    pub prompt_template: Option<Vec<PromptItemConfig>>,
    /// Dify-style structured output schema
    pub structured_output: Option<StructuredOutputConfig>,
    /// Reasoning format: "tagged" or "separated"
    pub reasoning_format: Option<String>,
}

#[derive(Debug)]
pub(crate) struct PromptItemConfig {
    pub role: String,
    pub text: String,
}

#[derive(Debug)]
pub(crate) struct StructuredOutputConfig {
    pub schema: Value,
}

impl LlmConfig {
    pub(crate) fn from_data(data: &Value) -> Result<Self> {
        // Support both Dify-style "model" object and simple string
        let model = if let Some(model_obj) = data.get("model").and_then(|v| v.as_object()) {
            // Dify-style ModelConfig: { provider, name, mode, completion_params }
            model_obj
                .get("name")
                .and_then(|v| v.as_str())
                .unwrap_or("")
                .to_string()
        } else {
            // Simple string model name
            data["model"].as_str().unwrap_or("").to_string()
        };

        if model.is_empty() {
            return Err(FlowError::InvalidDefinition(
                "llm: missing data.model".into(),
            ));
        }

        // Build API base and key from Dify-style model config if present
        let api_base = if let Some(model_obj) = data.get("model").and_then(|v| v.as_object()) {
            model_obj
                .get("completion_params")
                .and_then(|v| v.as_object())
                .and_then(|v| v.get("api_base"))
                .and_then(|v| v.as_str())
                .unwrap_or_else(|| data["api_base"].as_str().unwrap_or(DEFAULT_API_BASE))
                .to_string()
        } else {
            data["api_base"]
                .as_str()
                .unwrap_or(DEFAULT_API_BASE)
                .trim_end_matches('/')
                .to_string()
        };

        let api_key = if let Some(model_obj) = data.get("model").and_then(|v| v.as_object()) {
            model_obj
                .get("completion_params")
                .and_then(|v| v.as_object())
                .and_then(|v| v.get("api_key"))
                .and_then(|v| v.as_str())
                .unwrap_or("")
                .to_string()
        } else {
            data["api_key"].as_str().unwrap_or("").to_string()
        };

        // Get temperature and max_tokens from Dify-style completion_params or direct fields
        let (temperature, max_tokens) =
            if let Some(model_obj) = data.get("model").and_then(|v| v.as_object()) {
                if let Some(completion_params) = model_obj
                    .get("completion_params")
                    .and_then(|v| v.as_object())
                {
                    let temp = completion_params
                        .get("temperature")
                        .and_then(|v| v.as_f64())
                        .unwrap_or(DEFAULT_TEMPERATURE);
                    let max_tok = completion_params.get("max_tokens").and_then(|v| v.as_u64());
                    (temp, max_tok)
                } else {
                    (
                        data["temperature"].as_f64().unwrap_or(DEFAULT_TEMPERATURE),
                        data["max_tokens"].as_u64(),
                    )
                }
            } else {
                (
                    data["temperature"].as_f64().unwrap_or(DEFAULT_TEMPERATURE),
                    data["max_tokens"].as_u64(),
                )
            };

        // Support Dify-style prompt_template (array of PromptItems)
        let prompt_template = if let Some(template_arr) = data.get("prompt_template") {
            let items = parse_prompt_template(template_arr)?;
            if !items.is_empty() {
                Some(items)
            } else {
                None
            }
        } else {
            None
        };

        // Legacy a3s-style prompts (for backward compatibility)
        let user_prompt = data["user_prompt"].as_str().unwrap_or("").to_string();
        let system_prompt = data["system_prompt"].as_str().map(str::to_string);

        // Structured output — supports both Dify-style `structured_output: { schema: {...} }`
        // and a3s-style `structured_output_enabled: true` (enables JSON mode with empty schema)
        let structured_output =
            if let Some(so) = data.get("structured_output").and_then(|v| v.as_object()) {
                if let Some(schema) = so.get("schema") {
                    Some(StructuredOutputConfig {
                        schema: schema.clone(),
                    })
                } else {
                    None
                }
            } else if data
                .get("structured_output_enabled")
                .and_then(|v| v.as_bool())
                .unwrap_or(false)
            {
                // Enabled via boolean flag — use empty schema (plain JSON mode)
                Some(StructuredOutputConfig {
                    schema: json!({}),
                })
            } else {
                None
            };

        // Reasoning format
        let reasoning_format = data["reasoning_format"].as_str().map(str::to_string);

        Ok(Self {
            model,
            user_prompt,
            system_prompt,
            api_base,
            api_key,
            temperature,
            max_tokens,
            prompt_template,
            structured_output,
            reasoning_format,
        })
    }

    /// Parse only the connection-level fields (model, api_base, api_key, temperature,
    /// max_tokens). Does NOT require `user_prompt` — used by nodes that build their
    /// own prompts (e.g. `question-classifier`).
    pub(crate) fn from_connection_data(data: &Value) -> Result<Self> {
        let model = if let Some(model_obj) = data.get("model").and_then(|v| v.as_object()) {
            model_obj
                .get("name")
                .and_then(|v| v.as_str())
                .unwrap_or("")
                .to_string()
        } else {
            data["model"]
                .as_str()
                .ok_or_else(|| FlowError::InvalidDefinition("llm: missing data.model".into()))?
                .to_string()
        };

        let api_base = data["api_base"]
            .as_str()
            .unwrap_or(DEFAULT_API_BASE)
            .trim_end_matches('/')
            .to_string();
        let api_key = data["api_key"].as_str().unwrap_or("").to_string();
        let temperature = data["temperature"].as_f64().unwrap_or(DEFAULT_TEMPERATURE);
        let max_tokens = data["max_tokens"].as_u64();

        Ok(Self {
            model,
            user_prompt: String::new(),
            system_prompt: None,
            api_base,
            api_key,
            temperature,
            max_tokens,
            prompt_template: None,
            structured_output: None,
            reasoning_format: None,
        })
    }
}

/// Parse Dify-style prompt_template into PromptItemConfig vec.
fn parse_prompt_template(template: &Value) -> Result<Vec<PromptItemConfig>> {
    match template {
        Value::Array(arr) => {
            let mut items = Vec::new();
            for item in arr {
                let role = item
                    .get("role")
                    .and_then(|v| v.as_str())
                    .unwrap_or("user")
                    .to_string();
                // Support both jinja2_text and text
                let text =
                    if let Some(jinja_text) = item.get("jinja2_text").and_then(|v| v.as_str()) {
                        jinja_text.to_string()
                    } else {
                        item.get("text")
                            .and_then(|v| v.as_str())
                            .unwrap_or("")
                            .to_string()
                    };
                if !text.is_empty() {
                    items.push(PromptItemConfig { role, text });
                }
            }
            Ok(items)
        }
        Value::Object(obj) => {
            // Single prompt item
            let role = obj
                .get("role")
                .and_then(|v| v.as_str())
                .unwrap_or("user")
                .to_string();
            let text = if let Some(jinja_text) = obj.get("jinja2_text").and_then(|v| v.as_str()) {
                jinja_text.to_string()
            } else {
                obj.get("text")
                    .and_then(|v| v.as_str())
                    .unwrap_or("")
                    .to_string()
            };
            if text.is_empty() {
                Ok(Vec::new())
            } else {
                Ok(vec![PromptItemConfig { role, text }])
            }
        }
        _ => Ok(Vec::new()),
    }
}

/// Build chat messages from LlmConfig and Jinja context.
fn build_messages(
    config: &LlmConfig,
    jinja_ctx: &HashMap<String, Value>,
) -> Result<Vec<ChatMessage>> {
    let mut messages = Vec::new();

    // If Dify-style prompt_template is present, use it
    if let Some(ref template) = config.prompt_template {
        for item in template {
            let role = if item.role == "system" {
                "system".to_string()
            } else if item.role == "assistant" {
                "assistant".to_string()
            } else {
                "user".to_string()
            };
            let content = render(&item.text, jinja_ctx)?;
            messages.push(ChatMessage { role, content });
        }
        return Ok(messages);
    }

    // Legacy a3s-style: system_prompt + user_prompt
    if let Some(ref sys) = config.system_prompt {
        let content = render(sys, jinja_ctx)?;
        messages.push(ChatMessage {
            role: "system".into(),
            content,
        });
    }

    if !config.user_prompt.is_empty() {
        let content = render(&config.user_prompt, jinja_ctx)?;
        messages.push(ChatMessage {
            role: "user".into(),
            content,
        });
    }

    Ok(messages)
}

/// One message in a chat conversation.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub(crate) struct ChatMessage {
    pub role: String,
    pub content: String,
}

/// Extracted fields from a successful chat-completion response.
#[derive(Debug)]
pub(crate) struct CompletionResult {
    pub text: String,
    pub model: String,
    pub finish_reason: String,
    pub prompt_tokens: u64,
    pub completion_tokens: u64,
    pub total_tokens: u64,
    /// Reasoning content from models that support it (e.g., Claude, DeepSeek)
    pub reasoning: Option<String>,
}

/// Build a Jinja2 rendering context from the execution context.
///
/// Variables have lower priority; upstream inputs shadow same-named variables.
pub(crate) fn build_jinja_context(ctx: &ExecContext) -> HashMap<String, Value> {
    let mut map: HashMap<String, Value> = ctx.variables.clone();
    for (k, v) in &ctx.inputs {
        map.insert(k.clone(), v.clone());
    }
    map
}

/// Render a Jinja2 template string against the given context map.
pub(crate) fn render(template: &str, context: &HashMap<String, Value>) -> Result<String> {
    let env = minijinja::Environment::new();
    env.render_str(template, context)
        .map_err(|e| FlowError::Internal(format!("llm: template render error: {e}")))
}

/// Call the `/v1/chat/completions` endpoint and return the parsed result.
pub(crate) async fn do_chat_completion(
    api_base: &str,
    api_key: &str,
    model: &str,
    messages: Vec<ChatMessage>,
    temperature: Option<f64>,
    max_tokens: Option<u64>,
) -> Result<CompletionResult> {
    do_chat_completion_with_options(
        api_base,
        api_key,
        model,
        messages,
        temperature,
        max_tokens,
        None,
        None,
    )
    .await
}

/// Call the `/v1/chat/completions` endpoint with additional options.
pub(crate) async fn do_chat_completion_with_options(
    api_base: &str,
    api_key: &str,
    model: &str,
    messages: Vec<ChatMessage>,
    temperature: Option<f64>,
    max_tokens: Option<u64>,
    structured_output: Option<&StructuredOutputConfig>,
    reasoning_format: Option<&str>,
) -> Result<CompletionResult> {
    let mut body = json!({
        "model": model,
        "messages": messages,
        "temperature": temperature.unwrap_or(DEFAULT_TEMPERATURE),
    });
    if let Some(max_tok) = max_tokens {
        body["max_tokens"] = json!(max_tok);
    }

    // Add structured output if specified
    if let Some(so) = structured_output {
        body["response_format"] = json!({
            "type": "json_schema",
            "json_schema": so.schema,
        });
    }

    let url = format!("{api_base}/chat/completions");
    let client = reqwest::Client::new();
    let mut req = client.post(&url).json(&body);
    if !api_key.is_empty() {
        req = req.bearer_auth(api_key);
    }

    let response = req
        .send()
        .await
        .map_err(|e| FlowError::Internal(format!("llm: HTTP request failed: {e}")))?;

    let status = response.status();
    let text = response
        .text()
        .await
        .map_err(|e| FlowError::Internal(format!("llm: failed to read response body: {e}")))?;

    if !status.is_success() {
        return Err(FlowError::Internal(format!(
            "llm: API returned {status}: {text}"
        )));
    }

    let resp: Value = serde_json::from_str(&text)
        .map_err(|e| FlowError::Internal(format!("llm: failed to parse response JSON: {e}")))?;

    parse_completion_response(&resp, reasoning_format)
}

/// Parse a raw `/v1/chat/completions` JSON response into [`CompletionResult`].
///
/// Extracted as a separate function so it can be unit-tested without network.
///
/// `reasoning_format` controls how reasoning content is extracted:
/// - `None` or `"separated"`: reasoning from dedicated API field
/// - `"tagged"`: reasoning embedded in content with `<think>...</think>` or `<reasoning>...</reasoning>` tags
pub(crate) fn parse_completion_response(
    resp: &Value,
    reasoning_format: Option<&str>,
) -> Result<CompletionResult> {
    // Try standard content field first
    let raw_content = resp
        .pointer("/choices/0/message/content")
        .and_then(|v| v.as_str())
        .map(String::from);

    // Handle reasoning content from models like Claude (may be in reasoning block or alongside content)
    let separated_reasoning = resp
        .pointer("/choices/0/message/reasoning")
        .and_then(|v| v.as_str())
        .map(String::from);

    let (text, reasoning) = match (raw_content, separated_reasoning, reasoning_format) {
        // Tagged format: extract reasoning from content tags, strip tags from text
        (Some(content), _, Some("tagged")) => {
            let (extracted_reasoning, clean_text) = extract_tagged_reasoning(&content);
            (clean_text, extracted_reasoning)
        }
        // Separated format: use dedicated reasoning field
        (content, Some(reasoning), _) => {
            let text = content.or(Some(reasoning.clone())).unwrap_or_default();
            (text, Some(reasoning))
        }
        // No separate reasoning field: use content as-is
        (Some(content), None, _) => (content, None),
        // Neither content nor reasoning: error
        (None, None, _) => {
            return Err(FlowError::Internal(
                "llm: unexpected response shape (missing choices[0].message.content)".into(),
            ));
        }
    };

    let finish_reason = resp
        .pointer("/choices/0/finish_reason")
        .and_then(|v| v.as_str())
        .unwrap_or("stop")
        .to_string();

    let model = resp["model"].as_str().unwrap_or("unknown").to_string();
    let prompt_tokens = resp
        .pointer("/usage/prompt_tokens")
        .and_then(|v| v.as_u64())
        .unwrap_or(0);
    let completion_tokens = resp
        .pointer("/usage/completion_tokens")
        .and_then(|v| v.as_u64())
        .unwrap_or(0);
    let total_tokens = resp
        .pointer("/usage/total_tokens")
        .and_then(|v| v.as_u64())
        .unwrap_or(0);

    Ok(CompletionResult {
        text,
        model,
        finish_reason,
        prompt_tokens,
        completion_tokens,
        total_tokens,
        reasoning,
    })
}

/// Extract reasoning content from tagged content and return (reasoning, clean_text).
///
/// Supports:
/// - `<think>...</think>` (Claude-style)
/// - `<reasoning>...</reasoning>` (generic)
fn extract_tagged_reasoning(content: &str) -> (Option<String>, String) {
    // Try Claude's <think>...</think> tags first
    if let Some(start) = content.find("<think>") {
        if let Some(end) = content.find("</think>") {
            let reasoning = content[start + 8..end].trim().to_string();
            let before = &content[..start];
            let after = &content[end + 9..];
            let clean = format!("{}{}", before.trim(), after.trim()).trim().to_string();
            return (Some(reasoning), clean);
        }
    }

    // Try generic <reasoning>...</reasoning> tags
    if let Some(start) = content.find("<reasoning>") {
        if let Some(end) = content.find("</reasoning>") {
            let reasoning = content[start + 11..end].trim().to_string();
            let before = &content[..start];
            let after = &content[end + 12..];
            let clean = format!("{}{}", before.trim(), after.trim()).trim().to_string();
            return (Some(reasoning), clean);
        }
    }

    // No reasoning tags found
    (None, content.to_string())
}

// ── Tests ─────────────────────────────────────────────────────────────────────

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;
    use std::collections::HashMap;

    // ── Config validation ──────────────────────────────────────────────────

    #[test]
    fn rejects_missing_model() {
        let err = LlmConfig::from_data(&json!({ "user_prompt": "hi" })).unwrap_err();
        assert!(matches!(err, FlowError::InvalidDefinition(_)));
    }

    #[test]
    fn rejects_missing_user_prompt() {
        let err = LlmConfig::from_data(&json!({ "model": "gpt-4o" })).unwrap_err();
        assert!(matches!(err, FlowError::InvalidDefinition(_)));
    }

    #[test]
    fn applies_defaults() {
        let cfg = LlmConfig::from_data(&json!({
            "model": "gpt-4o-mini",
            "user_prompt": "hello"
        }))
        .unwrap();
        assert_eq!(cfg.api_base, DEFAULT_API_BASE);
        assert_eq!(cfg.api_key, "");
        assert!((cfg.temperature - DEFAULT_TEMPERATURE).abs() < 1e-9);
        assert!(cfg.max_tokens.is_none());
        assert!(cfg.system_prompt.is_none());
    }

    #[test]
    fn trailing_slash_stripped_from_api_base() {
        let cfg = LlmConfig::from_data(&json!({
            "model": "x",
            "user_prompt": "y",
            "api_base": "http://localhost:11434/v1/"
        }))
        .unwrap();
        assert_eq!(cfg.api_base, "http://localhost:11434/v1");
    }

    // ── Template rendering ─────────────────────────────────────────────────

    #[test]
    fn renders_user_prompt_with_variables() {
        let ctx_map = HashMap::from([("query".to_string(), json!("What is 2+2?"))]);
        let rendered = render("Answer: {{ query }}", &ctx_map).unwrap();
