        assert_eq!(pick_class("general inquiry", &classes), "general");
    }

    #[test]
    fn fallback_to_first_class_on_no_match() {
        let classes = make_classes();
        assert_eq!(pick_class("something completely unknown", &classes), "tech");
    }

