//! Trigger nodes — workflow entry points that fire based on schedule or webhook.
//!
//! These nodes are the **root** of a workflow DAG. They are not triggered by
//! upstream nodes; instead, the SafeClaw app layer fires the workflow based on
//! either a cron schedule or an incoming HTTP webhook request.
//!
//! | Node type | Description |
//! |-----------|-------------|
//! | `trigger-schedule` | Fires on a cron schedule |
//! | `trigger-webhook` | Fires when an HTTP request is received |
//!
//! When a workflow is triggered, the app layer creates an execution with the
//! trigger payload injected as flow variables. The trigger node then validates
//! its configuration and emits the trigger payload as its output for downstream
//! nodes to consume.

pub mod protocol;
pub mod schedule;
pub mod webhook;

pub use schedule::TriggerScheduleNode;
pub use webhook::TriggerWebhookNode;

//! Shared types for trigger nodes.

use serde::{Deserialize, Serialize};

/// Payload emitted by a `"trigger-schedule"` node when its workflow fires.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ScheduleTriggerPayload {
    /// The cron expression that triggered this run.
    pub cron: String,
    /// The timezone used to evaluate the cron expression.
    pub timezone: String,
    /// Unix timestamp in milliseconds when the trigger fired.
    pub fired_at: i64,
    /// Human-readable description of the cron expression.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub description: Option<String>,
}

/// Payload emitted by a `"trigger-webhook"` node when its workflow fires.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct WebhookTriggerPayload {
    /// HTTP method of the incoming webhook request.
    pub method: String,
    /// URL path that was called.
    pub path: String,
    /// Request headers.
    pub headers: std::collections::HashMap<String, String>,
    /// Parsed JSON body, or raw text if not JSON.
    #[serde(skip_serializing_if = "serde_json::Value::is_null")]
    pub body: serde_json::Value,
    /// Raw body string (available for non-JSON bodies).
    #[serde(skip_serializing_if = "Option::is_none")]
    pub raw_body: Option<String>,
}

//! `"trigger-schedule"` node — fires the workflow on a cron schedule.
//!
//! This node acts as the entry point of a DAG. When a workflow containing this
//! node is triggered by the SafeClaw scheduler, this node emits the trigger
//! payload (timestamp, cron expression, timezone) as output.
//!
//! The scheduler lives in the SafeClaw app layer, not in a3s-flow. This node
//! only validates the cron configuration and produces the trigger payload.
//!
//! # Config schema
//!
//! ```json
//! {
//!   "cron": "0 9 * * *",
//!   "timezone": "Asia/Shanghai"
//! }
//! ```
//!
//! | Field | Type | Required | Description |
//! |-------|------|----------|-------------|
//! | `cron` | string | ✅ | 5-field cron expression (standard cron format) |
//! | `timezone` | string | — | IANA timezone name (default: "UTC") |
//!
//! # Output schema
//!
//! ```json
//! {
//!   "cron": "0 9 * * *",
//!   "timezone": "Asia/Shanghai",
//!   "fired_at": 1710000000000,
//!   "description": "At 09:00"
//! }
//! ```

use async_trait::async_trait;
use serde_json::Value;
use std::str::FromStr;

use crate::error::{FlowError, Result};
use crate::node::{ExecContext, Node};

use super::protocol::ScheduleTriggerPayload;

pub struct TriggerScheduleNode;

#[async_trait]
impl Node for TriggerScheduleNode {
    fn node_type(&self) -> &str {
        "trigger-schedule"
    }

    async fn execute(&self, ctx: ExecContext) -> Result<Value> {
        // Support both Dify-style "cron" and a3s-style "cron_expression"
        let cron_expr = ctx
            .data
            .get("cron")
            .or_else(|| ctx.data.get("cron_expression"))
            .and_then(|v| v.as_str())
            .ok_or_else(|| {
                FlowError::InvalidDefinition(
                    "trigger-schedule: missing required field 'cron' (or 'cron_expression')"
                        .to_string(),
                )
            })?;

        // Validate the cron expression can be parsed.
        cron::Schedule::try_from(cron_expr).map_err(|e| {
            FlowError::InvalidDefinition(format!(
                "trigger-schedule: invalid cron expression '{}': {}",
                cron_expr, e
            ))
        })?;

        let timezone_str = ctx
            .data
            .get("timezone")
            .and_then(|v| v.as_str())
            .unwrap_or("UTC");

        // Validate timezone.
        let _tz = chrono_tz::Tz::from_str(timezone_str).map_err(|_| {
            FlowError::InvalidDefinition(format!(
                "trigger-schedule: unknown timezone '{}'",
                timezone_str
            ))
        })?;

        let fired_at = chrono::Utc::now().timestamp_millis();

        // Build a human-readable description from the cron expression.
        let description = describe_cron(cron_expr);

        let payload = ScheduleTriggerPayload {
            cron: cron_expr.to_string(),
            timezone: timezone_str.to_string(),
            fired_at,
            description,
        };

        Ok(serde_json::to_value(payload).expect("payload is serializable"))
    }
}

/// Returns a short human-readable description for a cron expression.
fn describe_cron(expr: &str) -> Option<String> {
    use std::fmt::Write;

    let schedule = cron::Schedule::try_from(expr).ok()?;

    // Get the next few runs to give a sense of the schedule.
    let next: Vec<String> = schedule
        .upcoming(chrono::Utc)
        .take(3)
        .map(|dt| dt.format("%Y-%m-%d %H:%M UTC").to_string())
        .collect();

    if next.is_empty() {
        return None;
    }

    let mut desc = String::new();
    if next.len() == 1 {
        write!(&mut desc, "Next run: {}", next[0]).ok();
    } else {
        write!(&mut desc, "Next runs: {}", next.join(", ")).ok();
    }
    Some(desc)
}

