            .run_named_flow("hello", HashMap::new())
            .await
            .unwrap();
        let state = service.get_execution(id).await.unwrap();
        assert!(matches!(
            state,
            ExecutionState::Running | ExecutionState::Completed(_)
        ));
    }
}

//! [`ExecutionStore`] — execution history persistence extension point.
//!
//! Implement [`ExecutionStore`] to persist [`FlowResult`] objects across process
//! restarts, enabling auditing, replay, and partial-resume workflows.
//!
//! Register a store via
//! [`FlowEngine::with_execution_store`](crate::engine::FlowEngine::with_execution_store).
//! The engine automatically saves completed results to the store.
//! [`MemoryExecutionStore`] is provided as an in-process default.

use std::collections::HashMap;
use std::sync::Arc;

use async_trait::async_trait;
use tokio::sync::RwLock;
use uuid::Uuid;

use crate::error::Result;
use crate::result::FlowResult;

/// Persistence layer for completed flow execution results.
///
/// # Example
///
/// ```rust
/// use a3s_flow::{ExecutionStore, FlowResult, MemoryExecutionStore};
/// use std::sync::Arc;
///
/// # #[tokio::main] async fn main() {
/// let store = Arc::new(MemoryExecutionStore::new());
/// let ids = store.list().await.unwrap();
/// assert!(ids.is_empty());
/// # }
/// ```
#[async_trait]
pub trait ExecutionStore: Send + Sync {
    /// Persist a completed execution result, keyed by `result.execution_id`.
    async fn save(&self, result: &FlowResult) -> Result<()>;

    /// Load a previously saved result by execution ID.
    ///
    /// Returns `None` if no result exists for the given ID.
    async fn load(&self, id: Uuid) -> Result<Option<FlowResult>>;

    /// List all stored execution IDs.
    async fn list(&self) -> Result<Vec<Uuid>>;

    /// Delete a stored result. No-op if the ID is not found.
    async fn delete(&self, id: Uuid) -> Result<()>;
}

/// An in-memory [`ExecutionStore`] backed by a `HashMap` under an `RwLock`.
///
/// Suitable for testing and short-lived processes. Data is lost on restart.
pub struct MemoryExecutionStore {
    inner: Arc<RwLock<HashMap<Uuid, FlowResult>>>,
}

impl MemoryExecutionStore {
    /// Create a new empty store.
    pub fn new() -> Self {
        Self {
            inner: Arc::new(RwLock::new(HashMap::new())),
        }
    }
}

impl Default for MemoryExecutionStore {
    fn default() -> Self {
        Self::new()
    }
}

#[async_trait]
impl ExecutionStore for MemoryExecutionStore {
    async fn save(&self, result: &FlowResult) -> Result<()> {
        self.inner
            .write()
            .await
            .insert(result.execution_id, result.clone());
        Ok(())
    }

    async fn load(&self, id: Uuid) -> Result<Option<FlowResult>> {
        Ok(self.inner.read().await.get(&id).cloned())
    }

    async fn list(&self) -> Result<Vec<Uuid>> {
        Ok(self.inner.read().await.keys().cloned().collect())
    }

    async fn delete(&self, id: Uuid) -> Result<()> {
        self.inner.write().await.remove(&id);
        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::{HashMap, HashSet};

    fn make_result() -> FlowResult {
        FlowResult {
            execution_id: Uuid::new_v4(),
            outputs: HashMap::new(),
            completed_nodes: HashSet::new(),
            skipped_nodes: HashSet::new(),
            context: HashMap::new(),
            total_elapsed_time_ms: 0,
            total_tokens: None,
            total_price: None,
        }
    }

    #[tokio::test]
    async fn save_and_load_round_trip() {
        let store = MemoryExecutionStore::new();
        let r = make_result();
        let id = r.execution_id;

        store.save(&r).await.unwrap();
        let loaded = store.load(id).await.unwrap().unwrap();
        assert_eq!(loaded.execution_id, id);
    }

    #[tokio::test]
    async fn load_unknown_id_returns_none() {
        let store = MemoryExecutionStore::new();
        let result = store.load(Uuid::new_v4()).await.unwrap();
        assert!(result.is_none());
    }

    #[tokio::test]
    async fn list_returns_all_saved_ids() {
        let store = MemoryExecutionStore::new();
        let r1 = make_result();
        let r2 = make_result();
        let id1 = r1.execution_id;
        let id2 = r2.execution_id;

        store.save(&r1).await.unwrap();
        store.save(&r2).await.unwrap();

        let ids = store.list().await.unwrap();
        assert_eq!(ids.len(), 2);
        assert!(ids.contains(&id1));
        assert!(ids.contains(&id2));
    }

    #[tokio::test]
    async fn delete_removes_entry() {
        let store = MemoryExecutionStore::new();
        let r = make_result();
        let id = r.execution_id;

        store.save(&r).await.unwrap();
        store.delete(id).await.unwrap();

        assert!(store.load(id).await.unwrap().is_none());
        assert!(store.list().await.unwrap().is_empty());
    }

    #[tokio::test]
    async fn save_overwrites_existing_entry() {
        let store = MemoryExecutionStore::new();
        let mut r = make_result();
        let id = r.execution_id;

        store.save(&r).await.unwrap();

        // Save again with a modified outputs map — should overwrite.
        r.outputs.insert("x".into(), serde_json::json!(42));
        store.save(&r).await.unwrap();

        let loaded = store.load(id).await.unwrap().unwrap();
        assert_eq!(loaded.outputs["x"], serde_json::json!(42));

        // Still only one entry.
        assert_eq!(store.list().await.unwrap().len(), 1);
    }
}

//! `"calculator"` built-in tool — evaluates mathematical expressions.

use async_trait::async_trait;
use serde_json::{json, Value};

use crate::error::{FlowError, Result};
use crate::tools::tool::{Tool, ToolOutput};

/// Simple math expression evaluator using the `meval` crate.
///
/// Supports standard arithmetic: `+`, `-`, `*`, `/`, `^` (power), parentheses,
/// and common functions: `sin`, `cos`, `tan`, `log`, `ln`, `sqrt`, `abs`, `exp`.
///
/// # Example
///
/// | expression | result |
/// |------------|--------|
/// | `2 + 3 * 4` | 14 |
/// | `sqrt(16)` | 4 |
/// | `sin(pi/2)` | 1 |
pub struct CalculatorTool;

impl CalculatorTool {
    pub fn new() -> Self {
        Self
    }
}

impl Default for CalculatorTool {
    fn default() -> Self {
        Self::new()
    }
}

#[async_trait]
impl Tool for CalculatorTool {
    fn tool_name(&self) -> &str {
        "calculator"
    }

    fn description(&self) -> &str {
        "Evaluate a mathematical expression and return the numeric result. Supports +, -, *, /, ^, sqrt, sin, cos, tan, log, ln, exp, abs, and parentheses."
    }

    fn parameters_schema(&self) -> Value {
        json!({
            "type": "object",
            "properties": {
                "expression": {
                    "type": "string",
                    "description": "Mathematical expression to evaluate, e.g. '2 + 3 * 4' or 'sqrt(16)'"
                }
            },
            "required": ["expression"]
        })
    }

    async fn invoke(&self, args: Value) -> Result<ToolOutput> {
        let expression = args["expression"]
            .as_str()
            .ok_or_else(|| FlowError::InvalidDefinition("calculator: expression is required".into()))?;

        let result = meval::eval_str(expression)
            .map_err(|e| FlowError::InvalidDefinition(format!("calculator: {}", e)))?;

        Ok(ToolOutput::ok(serde_json::to_string(&result).map_err(|e| {
            FlowError::Internal(format!("calculator: failed to serialize result: {}", e))
        })?))
    }
}

// Use meval for the actual evaluation
impl CalculatorTool {
    pub fn eval(&self, expression: &str) -> Result<f64> {
        meval::eval_str(expression)
            .map_err(|e| FlowError::InvalidDefinition(format!("calculator: {}", e)))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn calculator_basic() {
        let tool = CalculatorTool::new();
        assert!((tool.eval("2 + 3 * 4").unwrap() - 14.0).abs() < 1e-9);
        assert!((tool.eval("10.0 / 2.0").unwrap() - 5.0).abs() < 1e-9);
